d = json.load(open('/workspace/contracts/openapi.contract.json'))


def sch(s, ind=0):
    pad = '  ' * ind
    if s is None:
        return 'ANY'
    if '$ref' in s:
        return s['$ref'].split('/')[-1]
    for k in ('allOf', 'oneOf', 'anyOf'):
        if k in s:
            return k + '[' + ','.join(sch(x, ind) for x in s[k]) + ']'
    t = s.get('type')
    if t == 'object':
        props = s.get('properties')
        if not props:
            return 'object(free)'
        req = set(s.get('required', []))
        lines = ['{']
        for k, v in props.items():
            lines.append('  ' * (ind + 1) + k + ('*' if k in req else '') + ': ' + sch(v, ind + 1))
        lines.append(pad + '}')
        return '\n'.join(lines)
    if t == 'array':
        return 'array<' + sch(s.get('items'), ind) + '>'
    extra = ''
    if 'enum' in s:
        extra = 'enum' + str(s['enum'])
    if 'format' in s:
        extra += '(' + s['format'] + ')'
    if 'default' in s:
        extra += ' default=' + str(s['default'])
    if 'minimum' in s:
        extra += ' min=%s' % s['minimum']
    if 'maximum' in s:
        extra += ' max=%s' % s['maximum']
    return (t or '?') + extra


for p, v in d['paths'].items():
    for m, op in v.items():
        if m not in ('get', 'post', 'put', 'patch', 'delete'):
            continue
        print('=' * 100)
        print(m.upper(), p, '  opId:', op.get('operationId'))
        if op.get('summary'):
            print('  summary:', op['summary'])
        if op.get('description'):
            print('  desc:', op['description'])
        if 'security' in op:
            print('  security:', op['security'])
        for prm in op.get('parameters', []):
            print('  param', prm.get('in'), prm.get('name'), 'req=', prm.get('required'),
                  sch(prm.get('schema'), 1), prm.get('description', ''))
        rb = op.get('requestBody')
        if rb:
            for ct, mv in rb['content'].items():
                print('  body [' + ct + '] required=' + str(rb.get('required')))
                print('   ' + sch(mv.get('schema'), 1))
        for code, r in op.get('responses', {}).items():
            desc = r.get('description', '')
            if 'content' in r:
                for ct, mv in r['content'].items():
                    print('  resp', code, desc)
                    print('   ' + sch(mv.get('schema'), 1))
            else:
                print('  resp', code, desc, '(no content)')
