{"command":"create","path":"/workspace/backend/internal/domain/types.go","file_text":"// Package domain holds the persistent entity model for the lab sample network.
package domain

import "time"

type Role string

const (
	RoleAdministrator        Role = "administrator"
	RoleDispatcher           Role = "dispatcher"
	RoleRequester            Role = "requester"
	RoleCollectionProfession Role = "collection_professional"
	RoleDeliveryPartner      Role = "delivery_partner"
	RoleNodeHandler          Role = "node_handler"
	RoleLaboratoryTeam       Role = "laboratory_team"
)

// AllRoles lists every role the system recognises.
var AllRoles = []Role{
	RoleAdministrator,
	RoleDispatcher,
	RoleRequester,
	RoleCollectionProfession,
	RoleDeliveryPartner,
	RoleNodeHandler,
	RoleLaboratoryTeam,
}

func ValidRole(r Role) bool {
	for _, c := range AllRoles {
		if c == r {
			return true
		}
	}
	return false
}

type LocationFunction string

const (
	FunctionCollectionPoint LocationFunction = "collection_point"
	FunctionTransferPoint   LocationFunction = "transfer_point"
	FunctionHub             LocationFunction = "hub"
	FunctionLaboratory      LocationFunction = "laboratory"
)

func ValidLocationFunction(f LocationFunction) bool {
	switch f {
	case FunctionCollectionPoint, FunctionTransferPoint, FunctionHub, FunctionLaboratory:
		return true
	}
	return false
}

type Coordinate struct {
	Latitude  float64 `json:"latitude"`
	Longitude float64 `json:"longitude"`
}

type Certification struct {
	Code      string     `json:"code"`
	Active    bool       `json:"active"`
	ExpiresAt *time.Time `json:"expiresAt,omitempty"`
}

// User is an account with zero or more roles and an explicitly selected active role.
type User struct {
	UserID             string          `json:"userId"`
	Username           string          `json:"username"`
	PasswordHash       string          `json:"passwordHash"`
	Email              string          `json:"email,omitempty"`
	FullName           string          `json:"fullName,omitempty"`
	Phone              string          `json:"phone,omitempty"`
	Roles              []Role          `json:"roles"`
	Qualifications     []string        `json:"qualifications"`
	Certifications     []Certification `json:"certifications"`
	Active             bool            `json:"active"`
	AssignedLocationID string          `json:"assignedLocationId,omitempty"`
	Available          bool            `json:"available"`
	CapacityUnits      int             `json:"capacityUnits"`
	LatestLocation     *Coordinate     `json:"latestLocation,omitempty"`
	LocationRecordedAt *time.Time      `json:"locationRecordedAt,omitempty"`
	DeclineCount       int             `json:"declineCount"`
	DeclinePenaltyTil  *time.Time      `json:"declinePenaltyUntil,omitempty"`
	LastAssignedAt     *time.Time      `json:"lastAssignedAt,omitempty"`
	TotalAssignments   int             `json:"totalAssignments"`
	CreatedAt          time.Time       `json:"createdAt"`
	UpdatedAt          time.Time       `json:"updatedAt"`
}

func (u *User) HasRole(r Role) bool {
	for _, c := range u.Roles {
		if c == r {
			return true
		}
	}
	return false
}

func (u *User) HasQualification(code string) bool {
	if code == "" {
		return true
	}
	for _, q := range u.Qualifications {
		if q == code {
			return true
		}
	}
	return false
}

// HasActiveCertification reports whether the user holds a non-expired certification.
func (u *User) HasActiveCertification(code string, now time.Time) bool {
	if code == "" {
		return true
	}
	for _, c := range u.Certifications {
		if c.Code != code {
			continue
		}
		if !c.Active {
			return false
		}
		if c.ExpiresAt != nil && c.ExpiresAt.Before(now) {
			return false
		}
		return true
	}
	return false
}

type Session struct {
	Token      string    `json:"token"`
	UserID     string    `json:"userId"`
	ActiveRole Role      `json:"activeRole"`
	CreatedAt  time.Time `json:"createdAt"`
	ExpiresAt  time.Time `json:"expiresAt"`
	Revoked    bool      `json:"revoked"`
}

// Capacity tracks configured/reserved units for regular and cooled pools.
type Capacity struct {
	CapacityUnits       int `json:"capacityUnits"`
	ReservedUnits       int `json:"reservedUnits"`
	CooledCapacityUnits int `json:"cooledCapacityUnits"`
	CooledReservedUnits int `json:"cooledReservedUnits"`
}

func (c Capacity) AvailableUnits() int {
	if v := c.CapacityUnits - c.ReservedUnits; v > 0 {
		return v
	}
	return 0
}

func (c Capacity) CooledAvailableUnits() int {
	if v := c.CooledCapacityUnits - c.CooledReservedUnits; v > 0 {
		return v
	}
	return 0
}

type LocationFunctionStates struct {
	CollectionPoint bool `json:"collection_point"`
	TransferPoint   bool `json:"transfer_point"`
	Hub             bool `json:"hub"`
	Laboratory      bool `json:"laboratory"`
}

func (s LocationFunctionStates) Has(f LocationFunction) bool {
	switch f {
	case FunctionCollectionPoint:
		return s.CollectionPoint
	case FunctionTransferPoint:
		return s.TransferPoint
	case FunctionHub:
		return s.Hub
	case FunctionLaboratory:
		return s.Laboratory
	}
	return false
}

func (s *LocationFunctionStates) Set(f LocationFunction, v bool) {
	switch f {
	case FunctionCollectionPoint:
		s.CollectionPoint = v
	case FunctionTransferPoint:
		s.TransferPoint = v
	case FunctionHub:
		s.Hub = v
	case FunctionLaboratory:
		s.Laboratory = v
	}
}

// Location is a network node that may provide several functions at once.
type Location struct {
	LocationID      string                 `json:"locationId"`
	Name            string                 `json:"name"`
	Coordinate      Coordinate             `json:"coordinate"`
	CoverageKm      float64                `json:"coverageKm"`
	HandlingMinutes int                    `json:"handlingMinutes"`
	Active          bool                   `json:"active"`
	Functions       LocationFunctionStates `json:"functions"`
	Capacity        Capacity               `json:"capacity"`
	AcceptedTypes   []string               `json:"acceptedSampleTypeIds"`
	CreatedAt       time.Time              `json:"createdAt"`
	UpdatedAt       time.Time              `json:"updatedAt"`
}

func (l *Location) Accepts(sampleTypeID string) bool {
	for _, id := range l.AcceptedTypes {
		if id == sampleTypeID {
			return true
		}
	}
	return false
}

// FunctionActive reports whether the location and the specific function are both enabled.
func (l *Location) FunctionActive(f LocationFunction) bool {
	return l.Active && l.Functions.Has(f)
}

type Connection struct {
	ConnectionID   string    `json:"connectionId"`
	FromLocationID string    `json:"fromLocationId"`
	ToLocationID   string    `json:"toLocationId"`
	TravelMinutes  int       `json:"travelMinutes"`
	CostUnits      float64   `json:"costUnits"`
	Cooled         bool      `json:"cooled"`
	Active         bool      `json:"active"`
	Capacity       Capacity  `json:"capacity"`
	CreatedAt      time.Time `json:"createdAt"`
	UpdatedAt      time.Time `json:"updatedAt"`
}

type SampleType struct {
	SampleTypeID              string    `json:"sampleTypeId"`
	Name                      string    `json:"name"`
	QualifiedCollectorRequired bool     `json:"qualifiedCollectorRequired"`
	RequiredQualification     string    `json:"requiredQualification"`
	ContainerType             string    `json:"containerType"`
	TemperatureMinC           float64   `json:"temperatureMinC"`
	TemperatureMaxC           float64   `json:"temperatureMaxC"`
	IncompatibleSampleTypes   []string  `json:"incompatibleSampleTypes"`
	RequiresCooledRoute       bool      `json:"requiresCooledRoute"`
	BatchingAllowed           bool      `json:"batchingAllowed"`
	CreatedAt                 time.Time `json:"createdAt"`
	UpdatedAt                 time.Time `json:"updatedAt"`
}

type OriginType string

const (
	OriginHome   OriginType = "home"
	OriginClinic OriginType = "clinic"
	OriginNode   OriginType = "node"
)

type Request struct {
	RequestID           string     `json:"requestId"`
	RequesterID         string     `json:"requesterId"`
	SampleID            string     `json:"sampleId"`
	Origin              Coordinate `json:"origin"`
	OriginType          OriginType `json:"originType"`
	OriginNodeID        string     `json:"originNodeId,omitempty"`
	RequestedAt         time.Time  `json:"requestedAt"`
	DeliveryDeadline    time.Time  `json:"deliveryDeadline"`
	EarliestCollectionAt time.Time `json:"earliestCollectionAt"`
	LatestCollectionAt  time.Time  `json:"latestCollectionAt"`
	SampleTypeID        string     `json:"sampleTypeId"`
	CreatedAt           time.Time  `json:"createdAt"`
	CreatedByID         string     `json:"createdById"`
}

// Sample statuses.
const (
	SampleStatusRequested  = "requested"
	SampleStatusAssigned   = "assigned"
	SampleStatusCollected  = "collected"
	SampleStatusSealed     = "sealed"
	SampleStatusInTransit  = "in_transit"
	SampleStatusAtNode     = "at_node"
	SampleStatusAtLab      = "at_laboratory"
	SampleStatusReceived   = "received"
	SampleStatusCancelled  = "cancelled"
	SampleStatusException  = "exception"
	SampleStatusExpired    = "expired"
	SampleStatusUnserviceable = "unserviceable"
)

type ExceptionInfo struct {
	Reason     string    `json:"reason"`
	Kind       string    `json:"kind"`
	Detail     string    `json:"detail,omitempty"`
	OccurredAt time.Time `json:"occurredAt"`
	RaisedByID string    `json:"raisedById,omitempty"`
}

type Sample struct {
	SampleID                string         `json:"sampleId"`
	RequestID               string         `json:"requestId"`
	RequesterID             string         `json:"requesterId"`
	Origin                  Coordinate     `json:"origin"`
	OriginType              OriginType     `json:"originType"`
	OriginNodeID            string         `json:"originNodeId,omitempty"`
	RequestedAt             time.Time      `json:"requestedAt"`
	DeliveryDeadline        time.Time      `json:"deliveryDeadline"`
	EarliestCollectionAt    time.Time      `json:"earliestCollectionAt"`
	LatestCollectionAt      time.Time      `json:"latestCollectionAt"`
	SampleTypeID            string         `json:"sampleTypeId"`
	ContainerType           string         `json:"containerType"`
	TemperatureMinC         float64        `json:"temperatureMinC"`
	TemperatureMaxC         float64        `json:"temperatureMaxC"`
	IncompatibleSampleTypes []string       `json:"incompatibleSampleTypes"`
	Serviceability          string         `json:"serviceability"`
	ServiceabilityReason    string         `json:"serviceabilityReason,omitempty"`
	Status                  string         `json:"status"`
	Sealed                  bool           `json:"sealed"`
	SealedAt                *time.Time     `json:"sealedAt,omitempty"`
	CollectedAt             *time.Time     `json:"collectedAt,omitempty"`
	CurrentHolderID         string         `json:"currentHolderId,omitempty"`
	ActiveJourneyID         string         `json:"activeJourneyId,omitempty"`
	TargetLaboratoryID      string         `json:"targetLaboratoryId,omitempty"`
	ReceivedLaboratoryID    string         `json:"receivedLaboratoryId,omitempty"`
	ReceivedAt              *time.Time     `json:"receivedAt,omitempty"`
	Exception               *ExceptionInfo `json:"exception,omitempty"`
	LatestLocation          *Coordinate    `json:"latestLocation,omitempty"`
	LocationRecordedAt      *time.Time     `json:"locationRecordedAt,omitempty"`
	CompletedLegIDs         []string       `json:"completedLegIds"`
	PreSealed               bool           `json:"preSealed"`
	CreatedAt               time.Time      `json:"createdAt"`
	UpdatedAt               time.Time      `json:"updatedAt"`
}

func (s *Sample) Terminal() bool {
	switch s.Status {
	case SampleStatusReceived, SampleStatusCancelled, SampleStatusExpired, SampleStatusUnserviceable:
		return true
	}
	return false
}

func (s *Sample) RequiresCooled() bool {
	return s.TemperatureMaxC < 8
}

type RouteMode string

const (
	RouteDirect    RouteMode = "direct"
	RouteMultiStop RouteMode = "multi_stop"
	RouteBatched   RouteMode = "batched"
)

// Journey statuses.
const (
	JourneyStatusPlanned   = "planned"
	JourneyStatusActive    = "active"
	JourneyStatusCompleted = "completed"
	JourneyStatusCancelled = "cancelled"
	JourneyStatusReplaced  = "replaced"
	JourneyStatusExpired   = "expired"
	JourneyStatusException = "exception"
)

type StopType string

const (
	StopPickup   StopType = "pickup"
	StopHandoff  StopType = "handoff"
	StopDelivery StopType = "delivery"
)

type Stop struct {
	StopID       string     `json:"stopId"`
	LocationID   string     `json:"locationId"`
	StopType     StopType   `json:"stopType"`
	Sequence     int        `json:"sequence"`
	EstimatedAt  time.Time  `json:"estimatedAt"`
	DwellMinutes int        `json:"dwellMinutes"`
	Coordinate   Coordinate `json:"coordinate"`
	CompletedAt  *time.Time `json:"completedAt,omitempty"`
}

// Reservation records a capacity hold against a node, laboratory or connection pool.
type Reservation struct {
	ReservationID string `json:"reservationId"`
	ResourceID    string `json:"resourceId"`
	ResourceKind  string `json:"resourceKind"`
	SampleID      string `json:"sampleId"`
	Units         int    `json:"units"`
	Cooled        bool   `json:"cooled"`
	Released      bool   `json:"released"`
}

type Journey struct {
	JourneyID          string         `json:"journeyId"`
	ParentJourneyID    string         `json:"parentJourneyId,omitempty"`
	ReplacesJourneyID  string         `json:"replacesJourneyId,omitempty"`
	ReplacementID      string         `json:"replacementJourneyId,omitempty"`
	PlanVersion        int            `json:"planVersion"`
	RouteMode          RouteMode      `json:"routeMode"`
	Status             string         `json:"status"`
	SampleIDs          []string       `json:"sampleIds"`
	Stops              []Stop         `json:"orderedStops"`
	AssignmentIDs      []string       `json:"assignmentIds"`
	Reservations       []Reservation  `json:"reservations"`
	EstimatedDeliveryAt *time.Time    `json:"estimatedDeliveryAt,omitempty"`
	TotalCostUnits     float64        `json:"totalCostUnits"`
	LaboratoryID       string         `json:"laboratoryId,omitempty"`
	Valid              bool           `json:"valid"`
	CreatedAt          time.Time      `json:"createdAt"`
	UpdatedAt          time.Time      `json:"updatedAt"`
}

func (j *Journey) Unfinished() bool {
	switch j.Status {
	case JourneyStatusPlanned, JourneyStatusActive:
		return true
	}
	return false
}

// Assignment kinds.
const (
	AssignmentCollection = "collection"
	AssignmentTransport  = "transport"
	AssignmentNode       = "node"
	AssignmentLaboratory = "laboratory"
)

// Assignment statuses.
const (
	AssignStatusPending    = "pending"
	AssignStatusOffered    = "offered"
	AssignStatusAccepted   = "accepted"
	AssignStatusAtPickup   = "at_pickup"
	AssignStatusPickedUp   = "picked_up"
	AssignStatusInTransit  = "in_transit"
	AssignStatusArrived    = "arrived"
	AssignStatusDelivered  = "delivered"
	AssignStatusInProgress = "in_progress"
	AssignStatusCompleted  = "completed"
	AssignStatusCancelled  = "cancelled"
	AssignStatusException  = "exception"
	AssignStatusUnassigned = "unassigned"
)

type LocationPing struct {
	Coordinate Coordinate `json:"coordinate"`
	Sequence   int        `json:"sequence"`
	RecordedAt time.Time  `json:"recordedAt"`
}

// Assignment is one unit of offered/accepted work for one sample leg or node/lab handling step.
type Assignment struct {
	AssignmentID       string         `json:"assignmentId"`
	Kind               string         `json:"kind"`
	JourneyID          string         `json:"journeyId"`
	SampleID           string         `json:"sampleId"`
	SampleIDs          []string       `json:"sampleIds"`
	Sequence           int            `json:"sequence"`
	Status             string         `json:"status"`
	WorkerID           string         `json:"workerId,omitempty"`
	OfferedToID        string         `json:"offeredToId,omitempty"`
	OfferExpiresAt     *time.Time     `json:"offerExpiresAt,omitempty"`
	DeclinedByIDs      []string       `json:"declinedByIds"`
	FromLocationID     string         `json:"fromLocationId,omitempty"`
	ToLocationID       string         `json:"toLocationId,omitempty"`
	NodeID             string         `json:"nodeId,omitempty"`
	LaboratoryID       string         `json:"laboratoryId,omitempty"`
	RequiredRole       Role           `json:"requiredRole"`
	RequiredQualification string      `json:"requiredQualification,omitempty"`
	ConnectionID       string         `json:"connectionId,omitempty"`
	Cooled             bool           `json:"cooled"`
	PickupStopID       string         `json:"pickupStopId,omitempty"`
	DropoffStopID      string         `json:"dropoffStopId,omitempty"`
	LastPing           *LocationPing  `json:"lastPing,omitempty"`
	OfferAttempts      int            `json:"offerAttempts"`
	NoWorkerSince      *time.Time     `json:"noWorkerSince,omitempty"`
	CompletedAt        *time.Time     `json:"completedAt,omitempty"`
	CreatedAt          time.Time      `json:"createdAt"`
	UpdatedAt          time.Time      `json:"updatedAt"`
}

func (a *Assignment) Active() bool {
	switch a.Status {
	case AssignStatusCancelled, AssignStatusCompleted, AssignStatusException:
		return false
	}
	return true
}

