{"command":"create","path":"/workspace/backend/internal/core/auth.go","file_text":"package core

import (
	"context"
	"time"

	"labdelivery/internal/domain"
)

// Principal is the authenticated caller of one request.
type Principal struct {
	User       *domain.User
	Session    *domain.Session
	ActiveRole domain.Role
}

// HasRole reports whether the selected role matches one of the given roles.
func (p *Principal) HasRole(roles ...domain.Role) bool {
	for _, r := range roles {
		if p.ActiveRole == r {
			return true
		}
	}
	return false
}

// IsOps reports whether the caller acts as dispatcher or administrator.
func (p *Principal) IsOps() bool {
	return p.HasRole(domain.RoleDispatcher, domain.RoleAdministrator)
}

// Audiences lists the realtime audiences a session receives, following the selected role.
func (p *Principal) Audiences() []string {
	out := []string{userAudience(p.User.UserID)}
	if p.ActiveRole != "" {
		out = append(out, roleAudience(p.ActiveRole))
	}
	return out
}

// AuthenticateResult is returned by AuthenticateUser.
type AuthenticateResult struct {
	SessionToken string   `json:"sessionToken"`
	UserID       string   `json:"userId"`
	Roles        []string `json:"roles"`
	ActiveRole   string   `json:"activeRole"`
}

// AuthenticateUser verifies credentials and opens a session.
func (e *Engine) AuthenticateUser(ctx context.Context, username, password string) (*AuthenticateResult, int, error) {
	if username == "" || password == "" {
		return nil, 0, newErr(401, "invalid_credentials", "username and password are required")
	}
	res, status, err := e.mutate(ctx, "authenticate_user", "", "", "", func(t *txn) (any, int, error) {
		userID, ok := e.usersByName[lower(username)]
		if !ok {
			t.audit("sign_in", "user", lower(username), false,
				map[string]any{"reason": "unknown_username", "username": username})
			return nil, 0, newErr(401, "invalid_credentials", "invalid username or password")
		}
		user := e.users[userID]
		if !verifyPassword(user.PasswordHash, password) {
			t.audit("sign_in", "user", user.UserID, false,
				map[string]any{"reason": "bad_password", "username": username}, user.UserID)
			return nil, 0, newErr(401, "invalid_credentials", "invalid username or password")
		}
		if !user.Active {
			t.audit("sign_in", "user", user.UserID, false,
				map[string]any{"reason": "inactive_account"}, user.UserID)
			return nil, 0, newErr(401, "invalid_credentials", "account is inactive")
		}

		session := &domain.Session{
			Token:     newToken(),
			UserID:    user.UserID,
			CreatedAt: t.now,
			ExpiresAt: t.now.Add(e.cfg.SessionTTL),
		}
		// A single-role account starts with that role selected; multi-role accounts must choose.
		if len(user.Roles) == 1 {
			session.ActiveRole = user.Roles[0]
		}
		e.sessions[session.Token] = session
		t.actor = user
		t.role = session.ActiveRole
		t.saveSession(session)
		t.audit("sign_in", "user", user.UserID, true, map[string]any{
			"username":   user.Username,
			"roles":      rolesToStrings(user.Roles),
			"activeRole": string(session.ActiveRole),
		}, user.UserID)

		return &AuthenticateResult{
			SessionToken: session.Token,
			UserID:       user.UserID,
			Roles:        rolesToStrings(user.Roles),
			ActiveRole:   string(session.ActiveRole),
		}, 200, nil
	})
	if err != nil {
		return nil, 0, err
	}
	return resultAs[*AuthenticateResult](res), status, nil
}

// Authorize resolves a bearer [REDACTED] into a principal.
func (e *Engine) Authorize(token string) (*Principal, error) {
	e.mu.Lock()
	defer e.mu.Unlock()
	if token == "" {
		return nil, errUnauthorized("missing bearer [REDACTED]")
	}
	session, ok := e.sessions[token]
	if !ok || session.Revoked {
		return nil, errUnauthorized("invalid session token")
	}
	if session.ExpiresAt.Before(e.now()) {
		return nil, errUnauthorized("session expired")
	}
	user, ok := e.users[session.UserID]
	if !ok || !user.Active {
		return nil, errUnauthorized("account is not active")
	}
	// A role removed from the account can no longer be the selected working role.
	if session.ActiveRole != "" && !user.HasRole(session.ActiveRole) {
		session.ActiveRole = ""
	}
	return &Principal{User: user, Session: session, ActiveRole: session.ActiveRole}, nil
}

// RoleSelection is returned by SelectActiveRole.
type RoleSelection struct {
	ActiveRole string   `json:"activeRole"`
	Roles      []string `json:"roles"`
}

// SelectActiveRole switches the working role of the session without changing the account roles.
func (e *Engine) SelectActiveRole(ctx context.Context, p *Principal, role domain.Role) (*RoleSelection, int, error) {
	if !domain.ValidRole(role) {
		return nil, 0, errBadRequest("invalid_role", "unknown role")
	}
	res, status, err := e.mutate(ctx, "select_active_role", "", "", p.User.UserID, func(t *txn) (any, int, error) {
		t.actor = p.User
		t.role = p.ActiveRole
		user := e.users[p.User.UserID]
		if user == nil {
			return nil, 0, errNotFound("user not found")
		}
		if !user.HasRole(role) {
			t.audit("permission_check", "user", user.UserID, false,
				map[string]any{"requestedRole": string(role), "reason": "role_not_held"}, user.UserID)
			return nil, 0, errForbiddenCode("role_not_held", "the account does not hold this role")
		}
		session := e.sessions[p.Session.Token]
		if session == nil {
			return nil, 0, errUnauthorized("session not found")
		}
		previous := session.ActiveRole
		session.ActiveRole = role
		t.role = role
		t.saveSession(session)
		t.audit("select_active_role", "user", user.UserID, true, map[string]any{
			"previousRole": string(previous),
			"activeRole":   string(role),
			"roles":        rolesToStrings(user.Roles),
		}, user.UserID)
		return &RoleSelection{ActiveRole: string(role), Roles: rolesToStrings(user.Roles)}, 200, nil
	})
	if err != nil {
		return nil, 0, err
	}
	return resultAs[*RoleSelection](res), status, nil
}

// SignOut revokes the caller's session.
func (e *Engine) SignOut(ctx context.Context, p *Principal) error {
	_, _, err := e.mutate(ctx, "sign_out", "", "", p.User.UserID, func(t *txn) (any, int, error) {
		t.actor = p.User
		t.role = p.ActiveRole
		session := e.sessions[p.Session.Token]
		if session != nil {
			session.Revoked = true
			session.ExpiresAt = t.now
			delete(e.sessions, session.Token)
			t.cs.Delete("sessions", session.Token)
		}
		t.audit("sign_out", "user", p.User.UserID, true, map[string]any{}, p.User.UserID)
		return map[string]any{"status": "signed_out"}, 200, nil
	})
	return err
}

// requireRole enforces that the caller has selected a role permitted for the operation.
func (e *Engine) requireRole(p *Principal, action string, allowed ...domain.Role) error {
	if p.ActiveRole == "" {
		return errRoleNotSelected()
	}
	for _, r := range allowed {
		if p.ActiveRole == r {
			return nil
		}
	}
	return errForbidden("role " + string(p.ActiveRole) + " may not " + action)
}

// EnsureInitialAdministrator creates the first administrator when no users exist.
func (e *Engine) EnsureInitialAdministrator(ctx context.Context, username, password string) error {
	if username == "" || password == "" {
		return nil
	}
	_, _, err := e.mutate(ctx, "bootstrap_admin", "", "", "", func(t *txn) (any, int, error) {
		if len(e.users) > 0 {
			return map[string]any{"created": false}, 200, nil
		}
		user := &domain.User{
			UserID:         newUUID(),
			Username:       username,
			PasswordHash:   hashPassword(password),
			FullName:       "Initial Administrator",
			Roles:          []domain.Role{domain.RoleAdministrator},
			Qualifications: []string{},
			Certifications: []domain.Certification{},
			Active:         true,
			Available:      true,
			CapacityUnits:  0,
			CreatedAt:      t.now,
		}
		e.users[user.UserID] = user
		e.usersByName[lower(user.Username)] = user.UserID
		t.actor = user
		t.role = domain.RoleAdministrator
		t.saveUser(user)
		t.audit("create_user", "user", user.UserID, true, map[string]any{
			"username":     user.Username,
			"roles":        rolesToStrings(user.Roles),
			"bootstrapped": true,
		}, user.UserID)
		return map[string]any{"created": true}, 200, nil
	})
	return err
}

// EnsureDefaultSampleTypes seeds the four named sample types when none exist.
func (e *Engine) EnsureDefaultSampleTypes(ctx context.Context) error {
	_, _, err := e.mutate(ctx, "bootstrap_sample_types", "", "", "", func(t *txn) (any, int, error) {
		if len(e.sampleTypes) > 0 {
			return map[string]any{"created": 0}, 200, nil
		}
		var admin *domain.User
		for _, u := range e.users {
			if u.HasRole(domain.RoleAdministrator) {
				admin = u
				break
			}
		}
		t.actor = admin
		t.role = domain.RoleAdministrator

		amber := &domain.SampleType{
			SampleTypeID:               newUUID(),
			Name:                       "Amber",
			QualifiedCollectorRequired: true,
			RequiredQualification:      "amber_collection",
			ContainerType:              "standard",
			TemperatureMinC:            15,
			TemperatureMaxC:            25,
			BatchingAllowed:            true,
		}
		indigo := &domain.SampleType{
			SampleTypeID:               newUUID(),
			Name:                       "Indigo",
			QualifiedCollectorRequired: true,
			RequiredQualification:      "indigo_collection",
			ContainerType:              "sealed_rigid",
			TemperatureMinC:            15,
			TemperatureMaxC:            25,
			BatchingAllowed:            true,
		}
		frost := &domain.SampleType{
			SampleTypeID:               newUUID(),
			Name:                       "Frost",
			QualifiedCollectorRequired: true,
			RequiredQualification:      "frost_collection",
			ContainerType:              "cooled_box",
			TemperatureMinC:            2,
			TemperatureMaxC:            8,
			RequiresCooledRoute:        true,
			BatchingAllowed:            true,
		}
		pulse := &domain.SampleType{
			SampleTypeID:               newUUID(),
			Name:                       "Pulse",
			QualifiedCollectorRequired: true,
			RequiredQualification:      "pulse_collection",
			ContainerType:              "standard",
			TemperatureMinC:            15,
			TemperatureMaxC:            25,
			BatchingAllowed:            false,
		}
		// Indigo must never share a container with Amber.
		amber.IncompatibleSampleTypes = []string{indigo.SampleTypeID}
		indigo.IncompatibleSampleTypes = []string{amber.SampleTypeID}
		frost.IncompatibleSampleTypes = []string{}
		pulse.IncompatibleSampleTypes = []string{}

		for _, st := range []*domain.SampleType{amber, indigo, frost, pulse} {
			st.CreatedAt = t.now
			e.sampleTypes[st.SampleTypeID] = st
			t.saveSampleType(st)
			t.audit("create_sample_type", "sample_type", st.SampleTypeID, true, map[string]any{
				"name":          st.Name,
				"containerType": st.ContainerType,
				"seeded":        true,
			}, st.SampleTypeID)
		}
		return map[string]any{"created": 4}, 200, nil
	})
	return err
}

func rolesToStrings(roles []domain.Role) []string {
	out := make([]string, 0, len(roles))
	for _, r := range roles {
		out = append(out, string(r))
	}
	return out
}

// resultAs converts a mutate result, which may be a replayed raw JSON payload.
func resultAs[T any](v any) T {
	if typed, ok := v.(T); ok {
		return typed
	}
	var zero T
	if raw, ok := v.(interface{ MarshalJSON() ([]byte, error) }); ok {
		data, err := raw.MarshalJSON()
		if err == nil {
			_ = unmarshalInto(data, &zero)
		}
	}
	return zero
}

// PurgeExpiredSessions drops sessions that are past their expiry.
func (e *Engine) PurgeExpiredSessions(ctx context.Context) {
	e.mu.Lock()
	now := e.now()
	for token, s := range e.sessions {
		if s.ExpiresAt.Before(now) {
			delete(e.sessions, token)
		}
	}
	e.mu.Unlock()
	_ = e.st.DeleteExpiredSessions(ctx)
}

