{"command":"create","path":"/workspace/backend/internal/core/routing.go","file_text":"package core

import (
	"container/heap"
	"sort"
	"time"

	"labdelivery/internal/domain"
)

// Serviceability reasons, as pinned by the contract.
const (
	ReasonServiceable      = "serviceable"
	ReasonOutsideCoverage  = "outside_service_coverage"
	ReasonNoLaboratory     = "no_accepting_laboratory"
	ReasonNoRoute          = "no_route"
	ReasonNoCapacity       = "insufficient_capacity"
	ReasonDeadline         = "deadline_unreachable"
	ReasonHandlingRules    = "handling_rules_unsatisfiable"
)

// routeRequest describes what a plan must achieve.
type routeRequest struct {
	Origin       domain.Coordinate
	OriginType   domain.OriginType
	OriginNodeID string
	SampleType   *domain.SampleType
	Cooled       bool
	CollectAt    time.Time
	Deadline     time.Time
	// PreSealed skips the collection leg: transport starts at the entry node.
	PreSealed bool
	// SkipCapacity ignores current reservations, used to explain why a route failed.
	SkipCapacity bool
	// ExcludedLocations and ExcludedConnections are unavailable due to a disruption.
	ExcludedLocations   map[string]bool
	ExcludedConnections map[string]bool
}

// routePlan is a concrete feasible plan through the network.
type routePlan struct {
	EntryNodeID   string
	Path          []string
	Connections   []*domain.Connection
	LaboratoryID  string
	CollectAt     time.Time
	ArrivalAt     time.Time
	TotalCost     float64
	CollectTravel time.Duration
	// NodeArrival is the time the sample reaches each location in Path.
	NodeArrival []time.Time
}

// planRoute finds the fastest feasible plan, or the reason no plan exists.
func (e *Engine) planRoute(req routeRequest) (*routePlan, string) {
	if req.SampleType == nil {
		return nil, ReasonHandlingRules
	}

	entries, reason := e.entryNodes(req)
	if reason != "" {
		return nil, reason
	}
	labs := e.acceptingLaboratories(req.SampleType.SampleTypeID, req.ExcludedLocations)
	if len(labs) == 0 {
		return nil, ReasonNoLaboratory
	}

	best, found := e.searchPlans(req, entries, labs, req.Cooled, req.SkipCapacity)
	if found {
		if !best.ArrivalAt.After(req.Deadline) {
			return best, ReasonServiceable
		}
		// A feasible route exists but it is too slow for this deadline.
		return nil, ReasonDeadline
	}

	// Distinguish the cause: cooled-only restriction, capacity, or no connectivity at all.
	if req.Cooled {
		if _, ok := e.searchPlans(req, entries, labs, false, true); ok {
			return nil, ReasonHandlingRules
		}
		return nil, ReasonNoRoute
	}
	if !req.SkipCapacity {
		if _, ok := e.searchPlans(req, entries, labs, req.Cooled, true); ok {
			return nil, ReasonNoCapacity
		}
	}
	return nil, ReasonNoRoute
}

// entryNodes lists the active collection points that can take the sample into the network.
func (e *Engine) entryNodes(req routeRequest) ([]*domain.Location, string) {
	if req.OriginType == domain.OriginNode || req.OriginNodeID != "" {
		loc := e.locations[req.OriginNodeID]
		if loc == nil {
			return nil, ReasonOutsideCoverage
		}
		if req.ExcludedLocations[loc.LocationID] {
			return nil, ReasonOutsideCoverage
		}
		// A node origin must still provide an active entry function.
		if !loc.Active || !(loc.Functions.CollectionPoint || loc.Functions.Hub || loc.Functions.TransferPoint) {
			return nil, ReasonOutsideCoverage
		}
		return []*domain.Location{loc}, ""
	}

	var out []*domain.Location
	for _, loc := range e.locations {
		if !loc.FunctionActive(domain.FunctionCollectionPoint) || req.ExcludedLocations[loc.LocationID] {
			continue
		}
		radius := loc.CoverageKm
		if radius > e.cfg.MaxCoverageKm {
			radius = e.cfg.MaxCoverageKm
		}
		if haversineKm(req.Origin.Latitude, req.Origin.Longitude,
			loc.Coordinate.Latitude, loc.Coordinate.Longitude) <= radius {
			out = append(out, loc)
		}
	}
	if len(out) == 0 {
		return nil, ReasonOutsideCoverage
	}
	sort.Slice(out, func(i, j int) bool {
		di := haversineKm(req.Origin.Latitude, req.Origin.Longitude, out[i].Coordinate.Latitude, out[i].Coordinate.Longitude)
		dj := haversineKm(req.Origin.Latitude, req.Origin.Longitude, out[j].Coordinate.Latitude, out[j].Coordinate.Longitude)
		if di != dj {
			return di < dj
		}
		return out[i].LocationID < out[j].LocationID
	})
	return out, ""
}

func (e *Engine) acceptingLaboratories(sampleTypeID string, excluded map[string]bool) map[string]bool {
	out := map[string]bool{}
	for _, loc := range e.locations {
		if excluded[loc.LocationID] {
			continue
		}
		if loc.FunctionActive(domain.FunctionLaboratory) && loc.Accepts(sampleTypeID) {
			out[loc.LocationID] = true
		}
	}
	return out
}

type searchNode struct {
	locationID string
	minutes    float64
	cost       float64
	index      int
}

type nodeQueue []*searchNode

func (q nodeQueue) Len() int { return len(q) }
func (q nodeQueue) Less(i, j int) bool {
	if q[i].minutes != q[j].minutes {
		return q[i].minutes < q[j].minutes
	}
	return q[i].cost < q[j].cost
}
func (q nodeQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index, q[j].index = i, j
}
func (q *nodeQueue) Push(x any) {
	n := x.(*searchNode)
	n.index = len(*q)
	*q = append(*q, n)
}
func (q *nodeQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

// searchPlans runs a shortest-travel-time search from every entry node to any accepting
// laboratory and returns the fastest arriving plan.
func (e *Engine) searchPlans(req routeRequest, entries []*domain.Location, labs map[string]bool,
	cooledOnly, skipCapacity bool) (*routePlan, bool) {
	var best *routePlan
	for _, entry := range entries {
		plan, ok := e.searchFromEntry(req, entry, labs, cooledOnly, skipCapacity)
		if !ok {
			continue
		}
		if best == nil || plan.ArrivalAt.Before(best.ArrivalAt) ||
			(plan.ArrivalAt.Equal(best.ArrivalAt) && plan.TotalCost < best.TotalCost) {
			best = plan
		}
	}
	return best, best != nil
}

func (e *Engine) searchFromEntry(req routeRequest, entry *domain.Location, labs map[string]bool,
	cooledOnly, skipCapacity bool) (*routePlan, bool) {
	// Capacity at the entry node is required for every plan through it.
	if !skipCapacity && !e.locationHasCapacity(entry, req.Cooled) {
		return nil, false
	}

	outgoing := e.outgoingByLocation(cooledOnly, skipCapacity, req)

	dist := map[string]float64{entry.LocationID: 0}
	cost := map[string]float64{entry.LocationID: 0}
	prev := map[string]*domain.Connection{}
	visited := map[string]bool{}
	pq := &nodeQueue{}
	heap.Init(pq)
	heap.Push(pq, &searchNode{locationID: entry.LocationID, minutes: 0})

	var target string
	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchNode)
		if visited[cur.locationID] {
			continue
		}
		visited[cur.locationID] = true
		if labs[cur.locationID] {
			target = cur.locationID
			break
		}
		for _, conn := range outgoing[cur.locationID] {
			next := e.locations[conn.ToLocationID]
			if next == nil || !next.Active || req.ExcludedLocations[next.LocationID] {
				continue
			}
			// Intermediate stops must be able to hold the sample; destinations must be labs.
			isLab := labs[next.LocationID]
			if !isLab && !(next.Functions.Hub || next.Functions.TransferPoint || next.Functions.CollectionPoint) {
				continue
			}
			if !skipCapacity && !e.locationHasCapacity(next, req.Cooled) {
				continue
			}
			// Dwell at the arriving location applies unless it is the final laboratory.
			minutes := cur.minutes + float64(conn.TravelMinutes)
			if !isLab {
				minutes += float64(next.HandlingMinutes)
			}
			if old, ok := dist[next.LocationID]; !ok || minutes < old {
				dist[next.LocationID] = minutes
				cost[next.LocationID] = cost[cur.locationID] + conn.CostUnits
				prev[next.LocationID] = conn
				heap.Push(pq, &searchNode{locationID: next.LocationID, minutes: minutes,
					cost: cost[next.LocationID]})
			}
		}
	}
	if target == "" {
		return nil, false
	}

	// Rebuild the path from the laboratory back to the entry node.
	var conns []*domain.Connection
	path := []string{target}
	for cursor := target; cursor != entry.LocationID; {
		conn := prev[cursor]
		if conn == nil {
			return nil, false
		}
		conns = append(conns, conn)
		cursor = conn.FromLocationID
		path = append(path, cursor)
	}
	reverseStrings(path)
	reverseConnections(conns)

	plan := &routePlan{
		EntryNodeID:  entry.LocationID,
		Path:         path,
		Connections:  conns,
		LaboratoryID: target,
		CollectAt:    req.CollectAt,
		TotalCost:    cost[target],
	}

	// Timing: collection, travel to the entry node, then each hop with dwell at arrival.
	cursorTime := req.CollectAt
	if !req.PreSealed && req.OriginType != domain.OriginNode {
		km := haversineKm(req.Origin.Latitude, req.Origin.Longitude,
			entry.Coordinate.Latitude, entry.Coordinate.Longitude)
		travel := time.Duration(km / e.cfg.AverageSpeedKmh * float64(time.Hour))
		plan.CollectTravel = travel
		cursorTime = cursorTime.Add(travel)
	}
	cursorTime = cursorTime.Add(time.Duration(entry.HandlingMinutes) * time.Minute)
	plan.NodeArrival = []time.Time{cursorTime}
	for i, conn := range conns {
		cursorTime = cursorTime.Add(time.Duration(conn.TravelMinutes) * time.Minute)
		loc := e.locations[path[i+1]]
		if loc != nil {
			cursorTime = cursorTime.Add(time.Duration(loc.HandlingMinutes) * time.Minute)
		}
		plan.NodeArrival = append(plan.NodeArrival, cursorTime)
	}
	plan.ArrivalAt = cursorTime
	return plan, true
}

// outgoingByLocation indexes usable connections for the search.
func (e *Engine) outgoingByLocation(cooledOnly, skipCapacity bool, req routeRequest) map[string][]*domain.Connection {
	out := map[string][]*domain.Connection{}
	for _, conn := range e.connections {
		if !conn.Active || req.ExcludedConnections[conn.ConnectionID] {
			continue
		}
		if cooledOnly && !conn.Cooled {
			continue
		}
		if !skipCapacity && !connectionHasCapacity(conn, req.Cooled) {
			continue
		}
		out[conn.FromLocationID] = append(out[conn.FromLocationID], conn)
	}
	for _, list := range out {
		sort.Slice(list, func(i, j int) bool {
			if list[i].TravelMinutes != list[j].TravelMinutes {
				return list[i].TravelMinutes < list[j].TravelMinutes
			}
			return list[i].ConnectionID < list[j].ConnectionID
		})
	}
	return out
}

// locationHasCapacity reports whether the relevant pool at a location has a free unit.
// A pool with no configured units is treated as unconstrained.
func (e *Engine) locationHasCapacity(loc *domain.Location, cooled bool) bool {
	if cooled {
		if loc.Capacity.CooledCapacityUnits == 0 {
			return false
		}
		return loc.Capacity.CooledAvailableUnits() > 0
	}
	if loc.Capacity.CapacityUnits == 0 {
		return true
	}
	return loc.Capacity.AvailableUnits() > 0
}

func connectionHasCapacity(conn *domain.Connection, cooled bool) bool {
	if cooled {
		if conn.Capacity.CooledCapacityUnits == 0 {
			// A cooled connection without a configured cooled pool is unconstrained.
			return conn.Cooled
		}
		return conn.Capacity.CooledAvailableUnits() > 0
	}
	if conn.Capacity.CapacityUnits == 0 {
		return true
	}
	return conn.Capacity.AvailableUnits() > 0
}

func reverseStrings(s []string) {
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		s[i], s[j] = s[j], s[i]
	}
}

func reverseConnections(s []*domain.Connection) {
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		s[i], s[j] = s[j], s[i]
	}
}

// ServiceabilityCheck is the result of a dry-run serviceability check.
type ServiceabilityCheck struct {
	Serviceable            bool       `json:"serviceable"`
	Reason                 string     `json:"reason"`
	TargetLaboratoryID     string     `json:"targetLaboratoryId,omitempty"`
	EstimatedArrivalAt     *time.Time `json:"estimatedArrivalAt,omitempty"`
	ServiceabilityVersion  int        `json:"serviceabilityVersion"`
}

// CheckServiceabilityInput is the dry-run request.
type CheckServiceabilityInput struct {
	Origin               domain.Coordinate
	OriginType           domain.OriginType
	OriginNodeID         string
	SampleTypeID         string
	RequestedAt          time.Time
	DeliveryDeadline     time.Time
	EarliestCollectionAt *time.Time
	LatestCollectionAt   *time.Time
}

// CheckServiceability answers whether a request could be served, creating nothing.
func (e *Engine) CheckServiceability(p *Principal, in CheckServiceabilityInput) (any, error) {
	if p.ActiveRole == "" {
		return nil, errRoleNotSelected()
	}
	if err := validateCoordinate(in.Origin); err != nil {
		return nil, errBadRequest("invalid_origin", "origin coordinate is out of range")
	}
	if !validOriginType(in.OriginType) {
		return nil, errBadRequest("invalid_origin_type", "originType must be home, clinic or node")
	}
	window, err := resolveCollectionWindow(in.RequestedAt, in.DeliveryDeadline,
		in.EarliestCollectionAt, in.LatestCollectionAt)
	if err != nil {
		return nil, err
	}
	return e.read(func() (any, error) {
		sampleType := e.sampleTypes[in.SampleTypeID]
		if sampleType == nil {
			return nil, errNotFound("sample type not found")
		}
		if in.OriginType == domain.OriginNode && in.OriginNodeID == "" {
			return nil, errBadRequest("invalid_origin", "originNodeId is required for a node origin")
		}
		version := e.serviceabilityVersionLocked()
		plan, reason := e.planRoute(routeRequest{
			Origin:       in.Origin,
			OriginType:   in.OriginType,
			OriginNodeID: in.OriginNodeID,
			SampleType:   sampleType,
			Cooled:       sampleType.RequiresCooledRoute,
			CollectAt:    window.Earliest,
			Deadline:     in.DeliveryDeadline,
		})
		out := &ServiceabilityCheck{
			Serviceable:           reason == ReasonServiceable,
			Reason:                reason,
			ServiceabilityVersion: version,
		}
		if plan != nil {
			out.TargetLaboratoryID = plan.LaboratoryID
			out.EstimatedArrivalAt = timePtr(plan.ArrivalAt)
		}
		return out, nil
	})
}

func validOriginType(t domain.OriginType) bool {
	switch t {
	case domain.OriginHome, domain.OriginClinic, domain.OriginNode:
		return true
	}
	return false
}

type collectionWindow struct {
	Earliest time.Time
	Latest   time.Time
}

// resolveCollectionWindow applies the defaults and validates the window against the deadline.
func resolveCollectionWindow(requestedAt, deadline time.Time, earliest, latest *time.Time) (collectionWindow, error) {
	if requestedAt.IsZero() || deadline.IsZero() {
		return collectionWindow{}, errBadRequest("invalid_time", "requestedAt and deliveryDeadline are required")
	}
	w := collectionWindow{Earliest: requestedAt, Latest: deadline}
	if earliest != nil {
		w.Earliest = *earliest
	}
	if latest != nil {
		w.Latest = *latest
	}
	if !deadline.After(requestedAt) {
		return collectionWindow{}, errBadRequest("invalid_deadline", "deliveryDeadline must be after requestedAt")
	}
	if !w.Latest.After(w.Earliest) {
		return collectionWindow{}, errBadRequest("invalid_collection_window",
			"latestCollectionAt must be after earliestCollectionAt")
	}
	if w.Earliest.After(deadline) || w.Latest.After(deadline) {
		return collectionWindow{}, errBadRequest("invalid_collection_window",
			"the collection window must end no later than the delivery deadline")
	}
	return w, nil
}

// serviceabilityVersionLocked returns the version of the published snapshot.
func (e *Engine) serviceabilityVersionLocked() int {
	if e.snapshot == nil {
		return 1
	}
	return e.snapshot.Version
}
