{"command":"create","path":"/workspace/backend/internal/core/requests.go","file_text":"package core

import (
	"context"
	"time"

	"labdelivery/internal/domain"
)

// CollectionRequestInput is a request to collect and deliver one sample.
type CollectionRequestInput struct {
	RequesterID             string
	Origin                  domain.Coordinate
	OriginType              domain.OriginType
	OriginNodeID            string
	RequestedAt             time.Time
	DeliveryDeadline        time.Time
	EarliestCollectionAt    *time.Time
	LatestCollectionAt      *time.Time
	SampleTypeID            string
	ContainerType           string
	TemperatureMinC         float64
	TemperatureMaxC         float64
	IncompatibleSampleTypes []string
}

// RequestResult is the response shared by collection requests and pre-sealed ingestion.
type RequestResult struct {
	RequestID            string   `json:"requestId"`
	SampleID             string   `json:"sampleId"`
	Serviceability       string   `json:"serviceability"`
	ServiceabilityReason string   `json:"serviceabilityReason,omitempty"`
	ActiveAssignmentIDs  []string `json:"activeAssignmentIds"`
	EarliestCollectionAt string   `json:"earliestCollectionAt"`
	LatestCollectionAt   string   `json:"latestCollectionAt"`
	JourneyID            string   `json:"journeyId,omitempty"`
	TargetLaboratoryID   string   `json:"targetLaboratoryId,omitempty"`
	AlreadySealed        bool     `json:"alreadySealed"`
	OriginType           string   `json:"originType,omitempty"`
}

// CreateCollectionRequest registers a home or clinic collection request and plans it.
func (e *Engine) CreateCollectionRequest(ctx context.Context, p *Principal, in CollectionRequestInput,
	idemKey, idemHash string) (any, int, error) {
	if err := e.requireRole(p, "create collection requests",
		domain.RoleRequester, domain.RoleDispatcher, domain.RoleAdministrator); err != nil {
		return nil, 0, err
	}
	if err := validateCoordinate(in.Origin); err != nil {
		return nil, 0, errBadRequest("invalid_origin", "origin coordinate is out of range")
	}
	if !validOriginType(in.OriginType) {
		return nil, 0, errBadRequest("invalid_origin_type", "originType must be home, clinic or node")
	}
	window, err := resolveCollectionWindow(in.RequestedAt, in.DeliveryDeadline,
		in.EarliestCollectionAt, in.LatestCollectionAt)
	if err != nil {
		return nil, 0, err
	}
	if in.ContainerType == "" {
		return nil, 0, errBadRequest("handling_mismatch", "containerType is required")
	}
	if in.TemperatureMinC > in.TemperatureMaxC {
		return nil, 0, errBadRequest("handling_mismatch", "temperatureMinC must not exceed temperatureMaxC")
	}
	return e.mutate(ctx, "create_collection_request", idemKey, idemHash, p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		return e.createSampleAndPlan(t, p, in, window, false)
	})
}

// PreSealedInput registers a sample that was already collected and sealed.
type PreSealedInput = CollectionRequestInput

// IngestPreSealedSample registers an already-sealed sample held by the caller and plans only
// the transport legs needed from the point of registration onward.
func (e *Engine) IngestPreSealedSample(ctx context.Context, p *Principal, in PreSealedInput,
	idemKey, idemHash string) (any, int, error) {
	if err := e.requireRole(p, "register pre-sealed samples",
		domain.RoleCollectionProfession, domain.RoleDeliveryPartner,
		domain.RoleNodeHandler, domain.RoleLaboratoryTeam); err != nil {
		return nil, 0, err
	}
	if err := validateCoordinate(in.Origin); err != nil {
		return nil, 0, errBadRequest("invalid_origin", "origin coordinate is out of range")
	}
	// A pre-sealed sample must enter at a clinic or a network node, never at a home.
	if in.OriginType == domain.OriginHome {
		return nil, 0, errBadRequest("invalid_origin_type",
			"a pre-sealed sample may not originate at a home")
	}
	if !validOriginType(in.OriginType) {
		return nil, 0, errBadRequest("invalid_origin_type", "originType must be clinic or node")
	}
	window, err := resolveCollectionWindow(in.RequestedAt, in.DeliveryDeadline,
		in.EarliestCollectionAt, in.LatestCollectionAt)
	if err != nil {
		return nil, 0, err
	}
	if in.ContainerType == "" {
		return nil, 0, errBadRequest("handling_mismatch", "containerType is required")
	}
	if in.TemperatureMinC > in.TemperatureMaxC {
		return nil, 0, errBadRequest("handling_mismatch", "temperatureMinC must not exceed temperatureMaxC")
	}
	return e.mutate(ctx, "ingest_presealed_sample", idemKey, idemHash, p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		// The registering user must be the one who currently holds the sample.
		if in.RequesterID != "" && in.RequesterID != p.User.UserID && !p.IsOps() {
			return nil, 0, errBadRequest("invalid_holder",
				"the person registering a pre-sealed sample must be its current holder")
		}
		if in.OriginType == domain.OriginNode {
			if in.OriginNodeID == "" {
				return nil, 0, errBadRequest("invalid_origin", "originNodeId is required for a node origin")
			}
			// A node handler or laboratory operator may only ingest at their own site.
			switch p.ActiveRole {
			case domain.RoleNodeHandler, domain.RoleLaboratoryTeam:
				if p.User.AssignedLocationID != in.OriginNodeID {
					return nil, 0, errForbidden("workers may only register samples at their assigned location")
				}
			}
		}
		return e.createSampleAndPlan(t, p, in, window, true)
	})
}

// createSampleAndPlan creates the request, sample, journey, assignments and reservations.
// An unserviceable request is still recorded, without a journey or any reservation.
func (e *Engine) createSampleAndPlan(t *txn, p *Principal, in CollectionRequestInput,
	window collectionWindow, preSealed bool) (any, int, error) {
	sampleType := e.sampleTypes[in.SampleTypeID]
	if sampleType == nil {
		return nil, 0, errNotFound("sample type not found")
	}
	if in.OriginType == domain.OriginNode && in.OriginNodeID == "" {
		return nil, 0, errBadRequest("invalid_origin", "originNodeId is required for a node origin")
	}
	if in.OriginNodeID != "" {
		node := e.locations[in.OriginNodeID]
		if node == nil {
			return nil, 0, errNotFound("origin node not found")
		}
		if !node.Active {
			return nil, 0, errBadRequest("invalid_origin_state", "origin node is not active")
		}
	}
	// The declared handling attributes must match the sample type's rules.
	if in.ContainerType != sampleType.ContainerType {
		return nil, 0, errBadRequest("handling_mismatch",
			"containerType does not match the sample type requirement")
	}
	if in.TemperatureMinC != sampleType.TemperatureMinC || in.TemperatureMaxC != sampleType.TemperatureMaxC {
		return nil, 0, errBadRequest("handling_mismatch",
			"temperature range does not match the sample type requirement")
	}

	requesterID := p.User.UserID
	if in.RequesterID != "" {
		if in.RequesterID != p.User.UserID && !p.IsOps() {
			return nil, 0, errForbidden("requesters may only create their own requests")
		}
		if _, ok := e.users[in.RequesterID]; !ok {
			return nil, 0, errNotFound("requester not found")
		}
		requesterID = in.RequesterID
	}

	incompatible := in.IncompatibleSampleTypes
	if incompatible == nil {
		incompatible = stringsOrEmpty(sampleType.IncompatibleSampleTypes)
	}

	request := &domain.Request{
		RequestID:            newUUID(),
		RequesterID:          requesterID,
		Origin:               in.Origin,
		OriginType:           in.OriginType,
		OriginNodeID:         in.OriginNodeID,
		RequestedAt:          in.RequestedAt,
		DeliveryDeadline:     in.DeliveryDeadline,
		EarliestCollectionAt: window.Earliest,
		LatestCollectionAt:   window.Latest,
		SampleTypeID:         in.SampleTypeID,
		CreatedAt:            t.now,
		CreatedByID:          p.User.UserID,
	}
	sample := &domain.Sample{
		SampleID:                newUUID(),
		RequestID:               request.RequestID,
		RequesterID:             requesterID,
		Origin:                  in.Origin,
		OriginType:              in.OriginType,
		OriginNodeID:            in.OriginNodeID,
		RequestedAt:             in.RequestedAt,
		DeliveryDeadline:        in.DeliveryDeadline,
		EarliestCollectionAt:    window.Earliest,
		LatestCollectionAt:      window.Latest,
		SampleTypeID:            in.SampleTypeID,
		ContainerType:           in.ContainerType,
		TemperatureMinC:         in.TemperatureMinC,
		TemperatureMaxC:         in.TemperatureMaxC,
		IncompatibleSampleTypes: incompatible,
		Status:                  domain.SampleStatusRequested,
		CompletedLegIDs:         []string{},
		CreatedAt:               t.now,
	}
	request.SampleID = sample.SampleID

	if preSealed {
		sample.Sealed = true
		sample.PreSealed = true
		sample.SealedAt = timePtr(t.now)
		sample.CollectedAt = timePtr(t.now)
		sample.CurrentHolderID = p.User.UserID
		sample.Status = domain.SampleStatusSealed
		if in.OriginNodeID != "" {
			sample.Status = domain.SampleStatusAtNode
		}
	}

	collectAt := window.Earliest
	if preSealed {
		collectAt = t.now
		if collectAt.Before(window.Earliest) {
			collectAt = window.Earliest
		}
	}

	plan, reason := e.planRoute(routeRequest{
		Origin:       in.Origin,
		OriginType:   in.OriginType,
		OriginNodeID: in.OriginNodeID,
		SampleType:   sampleType,
		Cooled:       sampleType.RequiresCooledRoute,
		CollectAt:    collectAt,
		Deadline:     in.DeliveryDeadline,
		PreSealed:    preSealed,
	})

	out := &RequestResult{
		RequestID:            request.RequestID,
		SampleID:             sample.SampleID,
		ActiveAssignmentIDs:  []string{},
		EarliestCollectionAt: formatTime(window.Earliest),
		LatestCollectionAt:   formatTime(window.Latest),
		AlreadySealed:        preSealed,
		OriginType:           string(in.OriginType),
	}

	if plan == nil {
		sample.Serviceability = "unserviceable"
		sample.ServiceabilityReason = reason
		sample.Status = domain.SampleStatusUnserviceable
		e.requests[request.RequestID] = request
		e.samples[sample.SampleID] = sample
		t.saveRequest(request)
		t.saveSample(sample)
		t.audit("create_collection_request", "request", request.RequestID, true, map[string]any{
			"sampleId": sample.SampleID, "serviceability": "unserviceable", "reason": reason,
			"originType": string(in.OriginType),
		}, request.RequestID, sample.SampleID, requesterID)
		t.event("sample_unserviceable", "sample", sample.SampleID, map[string]any{
			"sampleId": sample.SampleID, "reason": reason,
		}, append(operationsAudience(), userAudience(requesterID))...)
		out.Serviceability = "unserviceable"
		out.ServiceabilityReason = reason
		return out, 201, nil
	}

	sample.Serviceability = "serviceable"
	e.requests[request.RequestID] = request
	e.samples[sample.SampleID] = sample

	journey, err := e.buildJourney(t, sample, plan)
	if err != nil {
		return nil, 0, err
	}

	t.saveRequest(request)
	t.saveSample(sample)

	action := "create_collection_request"
	if preSealed {
		action = "ingest_presealed_sample"
	}
	t.audit(action, "request", request.RequestID, true, map[string]any{
		"sampleId": sample.SampleID, "serviceability": "serviceable",
		"journeyId": journey.JourneyID, "targetLaboratoryId": plan.LaboratoryID,
		"originType": string(in.OriginType), "alreadySealed": preSealed,
	}, request.RequestID, sample.SampleID, journey.JourneyID, requesterID)
	if preSealed {
		t.audit("custody_assigned", "sample", sample.SampleID, true, map[string]any{
			"holderId": sample.CurrentHolderID, "reason": "presealed_registration",
		}, sample.SampleID, journey.JourneyID)
	}
	t.event("sample_created", "sample", sample.SampleID, map[string]any{
		"sampleId": sample.SampleID, "journeyId": journey.JourneyID,
	}, append(operationsAudience(), userAudience(requesterID))...)

	out.Serviceability = "serviceable"
	out.ServiceabilityReason = ReasonServiceable
	out.JourneyID = journey.JourneyID
	out.TargetLaboratoryID = plan.LaboratoryID
	out.ActiveAssignmentIDs = e.activeAssignmentIDs(sample.SampleID)
	return out, 201, nil
}

func (e *Engine) activeAssignmentIDs(sampleID string) []string {
	var out []string
	for _, a := range e.assignments {
		if a.Terminal() {
			continue
		}
		if containsString(a.Samples(), sampleID) {
			out = append(out, a.AssignmentID)
		}
	}
	sortStrings(out)
	return stringsOrEmpty(out)
}
