{"command":"create","path":"/workspace/backend/internal/core/custody.go","file_text":"package core

import (
	"context"
	"time"

	"labdelivery/internal/domain"
)

// CollectAndSealSample records collection and sealing by the assigned collector.
func (e *Engine) CollectAndSealSample(ctx context.Context, p *Principal, sampleID, assignmentID string,
	collectedAt time.Time, containerType string, observedTemperatureC float64,
	idemKey, idemHash string) (any, int, error) {
	if err := e.requireRole(p, "collect and seal samples", domain.RoleCollectionProfession); err != nil {
		return nil, 0, err
	}
	if idemKey == "" {
		return nil, 0, errIdempotencyRequired()
	}
	if collectedAt.IsZero() {
		return nil, 0, errBadRequest("invalid_time", "collectedAt is required")
	}
	return e.mutate(ctx, "collect_and_seal_sample", idemKey, idemHash, p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		sample := e.samples[sampleID]
		if sample == nil {
			return nil, 0, errNotFound("sample not found")
		}
		a := e.assignments[assignmentID]
		if a == nil {
			return nil, 0, errNotFound("assignment not found")
		}
		if a.Kind != domain.AssignmentCollection || !containsString(a.Samples(), sampleID) {
			return nil, 0, errConflict("invalid_sample_state", "assignment does not cover collecting this sample")
		}
		if a.Terminal() {
			return nil, 0, errConflict("assignment_inactive", "assignment is no longer active")
		}
		if a.WorkerID != p.User.UserID {
			t.audit("permission_check", "assignment", a.AssignmentID, false, map[string]any{
				"action": "collect_and_seal_sample", "reason": "not_assigned_worker",
			}, a.AssignmentID, sampleID, p.User.UserID)
			return nil, 0, errForbidden("only the assigned collector may collect this sample")
		}
		if a.Status != domain.AssignStatusAccepted && a.Status != domain.AssignStatusAtPickup &&
			a.Status != domain.AssignStatusInProgress {
			return nil, 0, errConflict("collection_not_ready", "assignment has not been accepted yet")
		}
		if sample.Sealed {
			return nil, 0, errConflict("invalid_sample_state", "sample is already sealed")
		}
		if sample.Terminal() {
			return nil, 0, errConflict("invalid_sample_state", "sample is in a terminal state")
		}
		if collectedAt.After(t.now.Add(5 * time.Minute)) {
			return nil, 0, errConflict("invalid_collection_time", "collectedAt is in the future")
		}
		// Collection must happen inside the collection window.
		if collectedAt.Before(sample.EarliestCollectionAt) || collectedAt.After(sample.LatestCollectionAt) {
			t.audit("collect_and_seal_sample", "sample", sample.SampleID, false, map[string]any{
				"reason": "outside_collection_window", "collectedAt": formatTime(collectedAt),
				"earliestCollectionAt": formatTime(sample.EarliestCollectionAt),
				"latestCollectionAt":   formatTime(sample.LatestCollectionAt),
			}, sample.SampleID, a.AssignmentID)
			return nil, 0, errConflict("outside_collection_window",
				"collection must take place inside the collection window")
		}
		sampleType := e.sampleTypes[sample.SampleTypeID]
		if sampleType != nil && sampleType.QualifiedCollectorRequired {
			if !p.User.HasActiveCertification(sampleType.RequiredQualification, t.now) {
				return nil, 0, errConflict("certification_inactive",
					"an active "+sampleType.RequiredQualification+" certification is required")
			}
		}

		compliant := e.handlingCompliant(sample, containerType, observedTemperatureC)
		if !compliant {
			// Record the observation and the resulting exception before rejecting the seal.
			e.raiseHandlingException(t, sample, containerType, observedTemperatureC, a.AssignmentID)
			return nil, 0, errBadRequest("handling_noncompliant",
				"observed container or temperature is outside the required range")
		}

		sample.Sealed = true
		sample.SealedAt = timePtr(collectedAt)
		sample.CollectedAt = timePtr(collectedAt)
		sample.CurrentHolderID = p.User.UserID
		sample.Status = domain.SampleStatusSealed
		t.saveSample(sample)

		a.Status = domain.AssignStatusCompleted
		a.CompletedAt = timePtr(collectedAt)
		t.saveAssignment(a)
		e.completeStop(t, a.JourneyID, a.DropoffStopID, collectedAt)

		t.audit("collect_and_seal_sample", "sample", sample.SampleID, true, map[string]any{
			"assignmentId": a.AssignmentID, "collectedAt": formatTime(collectedAt),
			"containerType": containerType, "observedTemperatureC": observedTemperatureC,
			"handlingCompliant": true, "currentHolderId": sample.CurrentHolderID,
		}, sample.SampleID, a.AssignmentID, sample.ActiveJourneyID)
		t.audit("custody_assigned", "sample", sample.SampleID, true, map[string]any{
			"holderId": sample.CurrentHolderID, "reason": "collection_sealed",
		}, sample.SampleID, sample.ActiveJourneyID)
		t.event("sample_sealed", "sample", sample.SampleID, map[string]any{
			"sampleId": sample.SampleID, "currentHolderId": sample.CurrentHolderID,
		}, append(operationsAudience(), userAudience(sample.RequesterID), userAudience(p.User.UserID))...)

		return map[string]any{
			"sampleId":          sample.SampleID,
			"status":            "sealed",
			"currentHolderId":   sample.CurrentHolderID,
			"sealedAt":          formatTime(collectedAt),
			"handlingCompliant": true,
		}, 201, nil
	})
}

// handlingCompliant checks an observation against the sample's required handling.
func (e *Engine) handlingCompliant(sample *domain.Sample, containerType string, temperatureC float64) bool {
	if containerType != sample.ContainerType {
		return false
	}
	return temperatureC >= sample.TemperatureMinC && temperatureC <= sample.TemperatureMaxC
}

func (e *Engine) raiseHandlingException(t *txn, sample *domain.Sample, containerType string,
	temperatureC float64, assignmentID string) {
	sample.Status = domain.SampleStatusException
	sample.Exception = &domain.ExceptionInfo{
		Reason:     "handling_noncompliant",
		Kind:       "handling",
		Detail:     "observed container or temperature outside the required range",
		OccurredAt: t.now,
		RaisedByID: actorID(t),
	}
	t.saveSample(sample)
	t.audit("sample_exception", "sample", sample.SampleID, true, map[string]any{
		"reason": "handling_noncompliant", "assignmentId": assignmentID,
		"observedContainerType": containerType, "observedTemperatureC": temperatureC,
		"requiredContainerType": sample.ContainerType,
		"temperatureMinC":       sample.TemperatureMinC, "temperatureMaxC": sample.TemperatureMaxC,
	}, sample.SampleID, assignmentID, sample.ActiveJourneyID)
	t.event("sample_exception", "sample", sample.SampleID, map[string]any{
		"sampleId": sample.SampleID, "reason": "handling_noncompliant",
	}, append(operationsAudience(), userAudience(sample.RequesterID))...)
}

func actorID(t *txn) string {
	if t.actor == nil {
		return ""
	}
	return t.actor.UserID
}

func (e *Engine) completeStop(t *txn, journeyID, stopID string, at time.Time) {
	if stopID == "" {
		return
	}
	journey := e.journeys[journeyID]
	if journey == nil {
		return
	}
	for i := range journey.Stops {
		if journey.Stops[i].StopID == stopID && journey.Stops[i].CompletedAt == nil {
			journey.Stops[i].CompletedAt = timePtr(at)
			if journey.Status == domain.JourneyStatusPlanned {
				journey.Status = domain.JourneyStatusActive
			}
			t.saveJourney(journey)
			return
		}
	}
}

// RecordHandlingCheckpoint records an observed container and temperature while holding custody.
func (e *Engine) RecordHandlingCheckpoint(ctx context.Context, p *Principal, sampleID, assignmentID,
	locationID, containerType string, observedTemperatureC float64, recordedAt time.Time,
	idemKey, idemHash string) (any, int, error) {
	if err := e.requireRole(p, "record handling checkpoints",
		domain.RoleCollectionProfession, domain.RoleDeliveryPartner,
		domain.RoleNodeHandler, domain.RoleLaboratoryTeam); err != nil {
		return nil, 0, err
	}
	if idemKey == "" {
		return nil, 0, errIdempotencyRequired()
	}
	if recordedAt.IsZero() {
		return nil, 0, errBadRequest("invalid_time", "recordedAt is required")
	}
	return e.mutate(ctx, "record_handling_checkpoint", idemKey, idemHash, p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		sample := e.samples[sampleID]
		if sample == nil {
			return nil, 0, errNotFound("sample not found")
		}
		a := e.assignments[assignmentID]
		if a == nil {
			return nil, 0, errNotFound("assignment not found")
		}
		if a.Terminal() {
			return nil, 0, errConflict("assignment_inactive", "assignment is no longer active")
		}
		if !containsString(a.Samples(), sampleID) {
			return nil, 0, errConflict("assignment_inactive", "assignment does not cover this sample")
		}
		if sample.Terminal() {
			return nil, 0, errConflict("terminal_sample", "sample is in a terminal state")
		}
		if a.WorkerID != p.User.UserID {
			return nil, 0, errForbidden("only the assigned worker may record a checkpoint")
		}
		if sample.CurrentHolderID != "" && sample.CurrentHolderID != p.User.UserID {
			return nil, 0, errForbidden("only the current holder may record a checkpoint")
		}
		if recordedAt.After(t.now.Add(5 * time.Minute)) {
			return nil, 0, errConflict("invalid_checkpoint_time", "recordedAt is in the future")
		}
		if journey := e.journeys[a.JourneyID]; journey != nil && !journey.Unfinished() {
			return nil, 0, errConflict("journey_inactive", "journey is no longer active")
		}
		if locationID != "" {
			if _, ok := e.locations[locationID]; !ok {
				return nil, 0, errNotFound("location not found")
			}
		}

		compliant := e.handlingCompliant(sample, containerType, observedTemperatureC)
		cp := &domain.Checkpoint{
			CheckpointID:         newUUID(),
			SampleID:             sampleID,
			AssignmentID:         assignmentID,
			LocationID:           locationID,
			ContainerType:        containerType,
			ObservedTemperatureC: observedTemperatureC,
			Compliant:            compliant,
			RecordedAt:           recordedAt,
			RecordedByID:         p.User.UserID,
		}
		t.saveCheckpoint(cp)

		t.audit("record_handling_checkpoint", "sample", sample.SampleID, true, map[string]any{
			"checkpointId": cp.CheckpointID, "assignmentId": assignmentID, "locationId": locationID,
			"containerType": containerType, "observedTemperatureC": observedTemperatureC,
			"compliant": compliant, "recordedAt": formatTime(recordedAt),
		}, sample.SampleID, assignmentID, cp.CheckpointID, sample.ActiveJourneyID)

		// An observation outside the required range marks the sample as an exception.
		if !compliant {
			e.raiseHandlingException(t, sample, containerType, observedTemperatureC, assignmentID)
		}
		return map[string]any{
			"checkpointId": cp.CheckpointID,
			"sampleId":     sample.SampleID,
			"compliant":    compliant,
			"sampleStatus": sample.Status,
		}, 201, nil
	})
}

// InitiateHandoff starts a two-sided custody transfer from the current holder to a receiver.
func (e *Engine) InitiateHandoff(ctx context.Context, p *Principal, sampleID, fromAssignmentID,
	toAssignmentID, receiverID string, initiatedAt time.Time, idemKey, idemHash string) (any, int, error) {
	if err := e.requireRole(p, "hand off samples",
		domain.RoleCollectionProfession, domain.RoleDeliveryPartner,
		domain.RoleNodeHandler, domain.RoleLaboratoryTeam); err != nil {
		return nil, 0, err
	}
	if idemKey == "" {
		return nil, 0, errIdempotencyRequired()
	}
	if initiatedAt.IsZero() {
		return nil, 0, errBadRequest("invalid_time", "initiatedAt is required")
	}
	return e.mutate(ctx, "initiate_handoff", idemKey, idemHash, p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		sample := e.samples[sampleID]
		if sample == nil {
			return nil, 0, errNotFound("sample not found")
		}
		from := e.assignments[fromAssignmentID]
		to := e.assignments[toAssignmentID]
		if from == nil || to == nil {
			return nil, 0, errNotFound("assignment not found")
		}
		receiver := e.users[receiverID]
		if receiver == nil {
			return nil, 0, errBadRequest("invalid_receiver", "receiver not found")
		}
		if !sample.Sealed {
			return nil, 0, errConflict("invalid_assignment_state", "sample is not sealed yet")
		}
		if sample.CurrentHolderID != p.User.UserID {
			return nil, 0, errConflict("not_current_holder", "only the current holder may hand off a sample")
		}
		if from.WorkerID != p.User.UserID {
			return nil, 0, errForbiddenCode("sender_assignment_mismatch",
				"the sending assignment does not belong to the caller")
		}
		if !containsString(from.Samples(), sampleID) || !containsString(to.Samples(), sampleID) {
			return nil, 0, errConflict("invalid_handoff_route", "assignments do not both cover this sample")
		}
		if from.JourneyID != to.JourneyID {
			return nil, 0, errConflict("invalid_handoff_route", "assignments belong to different journeys")
		}
		if to.Terminal() || from.Terminal() {
			return nil, 0, errConflict("invalid_assignment_state", "assignment is no longer active")
		}
		if to.WorkerID == "" {
			return nil, 0, errConflict("offer_not_available", "the receiving assignment has no accepted worker")
		}
		if to.WorkerID != receiverID {
			return nil, 0, errConflict("receiver_assignment_mismatch",
				"the receiving assignment belongs to another worker")
		}
		if receiverID == p.User.UserID {
			return nil, 0, errBadRequest("invalid_receiver", "a sample cannot be handed to its current holder")
		}
		if !receiver.Active || !receiver.Available {
			return nil, 0, errConflict("receiver_unavailable", "receiver is unavailable")
		}
		// Responsibility passes only between adjacent steps of the journey.
		if !e.adjacentAssignments(from, to) {
			return nil, 0, errConflict("nonadjacent_handoff", "assignments are not adjacent in the journey")
		}
		if initiatedAt.After(t.now.Add(5 * time.Minute)) {
			return nil, 0, errConflict("invalid_handoff_time", "initiatedAt is in the future")
		}
		// Repeated initiations must not create duplicate transfers of custody.
		if existing := e.pendingHandoff(sampleID); existing != nil {
			if existing.FromAssignmentID == fromAssignmentID && existing.ToAssignmentID == toAssignmentID {
				return map[string]any{
					"handoffId":       existing.HandoffID,
					"senderId":        existing.SenderID,
					"receiverId":      existing.ReceiverID,
					"currentHolderId": sample.CurrentHolderID,
					"status":          "pending",
				}, 201, nil
			}
			return nil, 0, errConflict("pending_handoff_exists", "another handoff is already pending")
		}
		// A transport leg must be driven to its destination before custody moves on.
		if from.Kind == domain.AssignmentTransport && from.Status != domain.AssignStatusDelivered &&
			from.Status != domain.AssignStatusArrived {
			return nil, 0, errConflict("transport_leg_incomplete", "the transport leg is not finished yet")
		}
		if err := e.priorLegsComplete(from); err != nil {
			return nil, 0, err
		}

		handoff := &domain.Handoff{
			HandoffID:        newUUID(),
			SampleID:         sampleID,
			FromAssignmentID: fromAssignmentID,
			ToAssignmentID:   toAssignmentID,
			SenderID:         p.User.UserID,
			ReceiverID:       receiverID,
			Status:           domain.HandoffPending,
			InitiatedAt:      initiatedAt,
			LocationID:       handoffLocation(from, to),
			CreatedAt:        t.now,
		}
		e.handoffs[handoff.HandoffID] = handoff
		t.saveHandoff(handoff)

		t.audit("initiate_handoff", "handoff", handoff.HandoffID, true, map[string]any{
			"sampleId": sampleID, "senderId": handoff.SenderID, "receiverId": receiverID,
			"fromAssignmentId": fromAssignmentID, "toAssignmentId": toAssignmentID,
			"initiatedAt": formatTime(initiatedAt),
		}, handoff.HandoffID, sampleID, fromAssignmentID, toAssignmentID, from.JourneyID)
		t.event("handoff_initiated", "handoff", handoff.HandoffID, map[string]any{
			"handoffId": handoff.HandoffID, "sampleId": sampleID, "receiverId": receiverID,
		}, append(operationsAudience(), userAudience(receiverID), userAudience(p.User.UserID))...)

		return map[string]any{
			"handoffId":       handoff.HandoffID,
			"senderId":        handoff.SenderID,
			"receiverId":      handoff.ReceiverID,
			"currentHolderId": sample.CurrentHolderID,
			"status":          "pending",
		}, 201, nil
	})
}

func handoffLocation(from, to *domain.Assignment) string {
	if to.Kind == domain.AssignmentNode {
		return to.NodeID
	}
	if to.Kind == domain.AssignmentLaboratory {
		return to.LaboratoryID
	}
	if from.ToLocationID != "" {
		return from.ToLocationID
	}
	return to.FromLocationID
}

// adjacentAssignments reports whether custody may pass directly between two steps.
func (e *Engine) adjacentAssignments(from, to *domain.Assignment) bool {
	fromSite := assignmentExitLocation(from)
	toSite := assignmentEntryLocation(to)
	if fromSite == "" || toSite == "" {
		return true
	}
	return fromSite == toSite
}

func assignmentExitLocation(a *domain.Assignment) string {
	switch a.Kind {
	case domain.AssignmentCollection, domain.AssignmentTransport:
		return a.ToLocationID
	case domain.AssignmentNode:
		return a.NodeID
	case domain.AssignmentLaboratory:
		return a.LaboratoryID
	}
	return ""
}

func assignmentEntryLocation(a *domain.Assignment) string {
	switch a.Kind {
	case domain.AssignmentTransport:
		return a.FromLocationID
	case domain.AssignmentNode:
		return a.NodeID
	case domain.AssignmentLaboratory:
		return a.LaboratoryID
	case domain.AssignmentCollection:
		return a.ToLocationID
	}
	return ""
}

// priorLegsComplete ensures earlier legs of the same journey are finished first.
func (e *Engine) priorLegsComplete(from *domain.Assignment) error {
	journey := e.journeys[from.JourneyID]
	if journey == nil {
		return nil
	}
	for _, id := range journey.AssignmentIDs {
		other := e.assignments[id]
		if other == nil || other.AssignmentID == from.AssignmentID {
			continue
		}
		if other.Kind != domain.AssignmentTransport && other.Kind != domain.AssignmentCollection {
			continue
		}
		if other.Sequence < from.Sequence && !other.Terminal() &&
			other.Status != domain.AssignStatusDelivered {
			return errConflict("prior_leg_incomplete", "an earlier leg of this journey is unfinished")
		}
	}
	return nil
}

func (e *Engine) pendingHandoff(sampleID string) *domain.Handoff {
	for _, h := range e.handoffs {
		if h.SampleID == sampleID && h.Status == domain.HandoffPending {
			return h
		}
	}
	return nil
}

// ConfirmHandoff records one side's confirmation; custody moves only when both have confirmed.
func (e *Engine) ConfirmHandoff(ctx context.Context, p *Principal, handoffID, side string,
	confirmedAt time.Time, idemKey, idemHash string) (any, int, error) {
	if p.ActiveRole == "" {
		return nil, 0, errRoleNotSelected()
	}
	if idemKey == "" {
		return nil, 0, errIdempotencyRequired()
	}
	if side != "sender" && side != "receiver" {
		return nil, 0, errBadRequest("invalid_confirmation_side", "confirmationSide must be sender or receiver")
	}
	if confirmedAt.IsZero() {
		return nil, 0, errBadRequest("invalid_time", "confirmedAt is required")
	}
	return e.mutate(ctx, "confirm_handoff", idemKey, idemHash, p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		handoff := e.handoffs[handoffID]
		if handoff == nil {
			return nil, 0, errNotFound("handoff not found")
		}
		sample := e.samples[handoff.SampleID]
		if sample == nil {
			return nil, 0, errNotFound("sample not found")
		}
		if handoff.Status == domain.HandoffConfirmed {
			// A repeated confirmation is acknowledged without transferring custody again.
			return map[string]any{
				"handoffId":         handoff.HandoffID,
				"status":            "confirmed",
				"senderConfirmed":   handoff.SenderConfirmed,
				"receiverConfirmed": handoff.ReceiverConfirmed,
				"currentHolderId":   sample.CurrentHolderID,
			}, 201, nil
		}
		if handoff.Status != domain.HandoffPending {
			return nil, 0, errConflict("handoff_inactive", "handoff is no longer pending")
		}
		if confirmedAt.After(t.now.Add(5 * time.Minute)) {
			return nil, 0, errConflict("invalid_confirmation_time", "confirmedAt is in the future")
		}
		if confirmedAt.Before(handoff.InitiatedAt) {
			return nil, 0, errConflict("invalid_confirmation_time", "confirmedAt precedes the handoff")
		}
		expected := handoff.SenderID
		if side == "receiver" {
			expected = handoff.ReceiverID
		}
		if p.User.UserID != expected {
			t.audit("permission_check", "handoff", handoff.HandoffID, false, map[string]any{
				"action": "confirm_handoff", "side": side, "reason": "wrong_party",
			}, handoff.HandoffID, handoff.SampleID, p.User.UserID)
			return nil, 0, errForbidden("only the " + side + " may confirm this side of the handoff")
		}

		if side == "sender" {
			handoff.SenderConfirmed = true
		} else {
			handoff.ReceiverConfirmed = true
		}
		t.audit("confirm_handoff", "handoff", handoff.HandoffID, true, map[string]any{
			"side": side, "sampleId": handoff.SampleID, "confirmedAt": formatTime(confirmedAt),
			"senderConfirmed": handoff.SenderConfirmed, "receiverConfirmed": handoff.ReceiverConfirmed,
		}, handoff.HandoffID, handoff.SampleID, p.User.UserID)

		if handoff.SenderConfirmed && handoff.ReceiverConfirmed {
			handoff.Status = domain.HandoffConfirmed
			handoff.ConfirmedAt = timePtr(confirmedAt)
			// The receiver becomes the holder only now that both sides have confirmed.
			previousHolder := sample.CurrentHolderID
			sample.CurrentHolderID = handoff.ReceiverID
			if from := e.assignments[handoff.FromAssignmentID]; from != nil && !from.Terminal() {
				from.Status = domain.AssignStatusCompleted
				from.CompletedAt = timePtr(confirmedAt)
				t.saveAssignment(from)
				sample.CompletedLegIDs = appendUnique(sample.CompletedLegIDs, from.AssignmentID)
				e.completeStop(t, from.JourneyID, from.DropoffStopID, confirmedAt)
			}
			to := e.assignments[handoff.ToAssignmentID]
			if to != nil {
				sample.Status = statusForAssignment(to)
				if to.Status == domain.AssignStatusAccepted {
					to.Status = domain.AssignStatusInProgress
					t.saveAssignment(to)
				}
			}
			if handoff.LocationID != "" {
				if loc := e.locations[handoff.LocationID]; loc != nil {
					sample.LatestLocation = &loc.Coordinate
					sample.LocationRecordedAt = timePtr(confirmedAt)
				}
			}
			t.saveSample(sample)
			t.audit("custody_transferred", "sample", sample.SampleID, true, map[string]any{
				"handoffId": handoff.HandoffID, "fromHolderId": previousHolder,
				"toHolderId": sample.CurrentHolderID, "confirmedAt": formatTime(confirmedAt),
			}, sample.SampleID, handoff.HandoffID, handoff.SampleID, sample.ActiveJourneyID)
			t.event("custody_transferred", "sample", sample.SampleID, map[string]any{
				"sampleId": sample.SampleID, "currentHolderId": sample.CurrentHolderID,
			}, append(operationsAudience(), userAudience(sample.RequesterID),
				userAudience(handoff.SenderID), userAudience(handoff.ReceiverID))...)
		}
		t.saveHandoff(handoff)

		return map[string]any{
			"handoffId":         handoff.HandoffID,
			"status":            handoff.Status,
			"senderConfirmed":   handoff.SenderConfirmed,
			"receiverConfirmed": handoff.ReceiverConfirmed,
			"currentHolderId":   sample.CurrentHolderID,
		}, 201, nil
	})
}

func statusForAssignment(a *domain.Assignment) string {
	switch a.Kind {
	case domain.AssignmentTransport:
		return domain.SampleStatusInTransit
	case domain.AssignmentNode:
		return domain.SampleStatusAtNode
	case domain.AssignmentLaboratory:
		return domain.SampleStatusAtLab
	}
	return domain.SampleStatusInTransit
}

// UpdateAssignmentProgress records a worker's progress through their assigned leg.
func (e *Engine) UpdateAssignmentProgress(ctx context.Context, p *Principal, assignmentID, status string,
	occurredAt time.Time, idemKey, idemHash string) (any, int, error) {
	if p.ActiveRole == "" {
		return nil, 0, errRoleNotSelected()
	}
	if idemKey == "" {
		return nil, 0, errIdempotencyRequired()
	}
	if occurredAt.IsZero() {
		return nil, 0, errBadRequest("invalid_time", "occurredAt is required")
	}
	if !validProgressStatus(status) {
		return nil, 0, errBadRequest("invalid_json", "unknown progress status")
	}
	return e.mutate(ctx, "update_assignment_progress", idemKey, idemHash, p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		a := e.assignments[assignmentID]
		if a == nil {
			return nil, 0, errNotFound("assignment not found")
		}
		if a.Terminal() {
			return nil, 0, errConflict("assignment_inactive", "assignment is no longer active")
		}
		if a.WorkerID != p.User.UserID {
			t.audit("permission_check", "assignment", a.AssignmentID, false, map[string]any{
				"action": "update_assignment_progress", "reason": "not_assigned_worker",
			}, a.AssignmentID, p.User.UserID)
			return nil, 0, errForbiddenCode("ineligible_worker", "only the assigned worker may report progress")
		}
		if p.ActiveRole != a.RequiredRole {
			return nil, 0, errForbiddenCode("ineligible_worker",
				"this assignment is worked under the "+string(a.RequiredRole)+" role")
		}
		if a.Status == domain.AssignStatusPending || a.Status == domain.AssignStatusOffered {
			return nil, 0, errConflict("assignment_not_ready", "assignment has not been accepted")
		}
		if occurredAt.After(t.now.Add(5 * time.Minute)) {
			return nil, 0, errConflict("invalid_progress_time", "occurredAt is in the future")
		}
		if !validProgressTransition(a.Status, status) {
			return nil, 0, errConflict("invalid_transition",
				"cannot move from "+a.Status+" to "+status)
		}

		sample := e.samples[a.SampleID]
		if sample == nil {
			return nil, 0, errNotFound("sample not found")
		}
		// Transport may only begin once the sample has been collected and sealed.
		if a.Kind == domain.AssignmentTransport && !sample.Sealed {
			return nil, 0, errConflict("collection_required", "the sample has not been collected and sealed")
		}
		// Moving the sample requires actually holding it.
		if a.Kind == domain.AssignmentTransport &&
			(status == domain.AssignStatusInTransit || status == domain.AssignStatusDelivered) &&
			sample.CurrentHolderID != p.User.UserID {
			return nil, 0, errConflict("custody_required", "the worker does not currently hold the sample")
		}

		previous := a.Status
		a.Status = status
		if status == domain.AssignStatusCompleted {
			a.CompletedAt = timePtr(occurredAt)
			sample.CompletedLegIDs = appendUnique(sample.CompletedLegIDs, a.AssignmentID)
			t.saveSample(sample)
		}
		t.saveAssignment(a)

		if status == domain.AssignStatusPickedUp || status == domain.AssignStatusAtPickup {
			e.completeStop(t, a.JourneyID, a.PickupStopID, occurredAt)
		}
		if status == domain.AssignStatusDelivered || status == domain.AssignStatusArrived {
			e.completeStop(t, a.JourneyID, a.DropoffStopID, occurredAt)
		}
		if status == domain.AssignStatusInTransit && sample.Status != domain.SampleStatusInTransit {
			sample.Status = domain.SampleStatusInTransit
			t.saveSample(sample)
		}

		t.audit("update_assignment_progress", "assignment", a.AssignmentID, true, map[string]any{
			"previousStatus": previous, "status": status, "occurredAt": formatTime(occurredAt),
			"sampleId": a.SampleID,
		}, a.AssignmentID, a.SampleID, a.JourneyID, p.User.UserID)
		t.event("assignment_progress", "assignment", a.AssignmentID, map[string]any{
			"assignmentId": a.AssignmentID, "status": status, "sampleId": a.SampleID,
		}, append(operationsAudience(), userAudience(sample.RequesterID), userAudience(p.User.UserID))...)

		return map[string]any{
			"assignmentId": a.AssignmentID,
			"sampleId":     a.SampleID,
			"status":       a.Status,
		}, 201, nil
	})
}

func validProgressStatus(s string) bool {
	switch s {
	case domain.AssignStatusAtPickup, domain.AssignStatusPickedUp, domain.AssignStatusInTransit,
		domain.AssignStatusArrived, domain.AssignStatusDelivered, domain.AssignStatusInProgress,
		domain.AssignStatusCompleted:
		return true
	}
	return false
}

// progressOrder ranks assignment statuses so progress only moves forward.
var progressOrder = map[string]int{
	domain.AssignStatusAccepted:   0,
	domain.AssignStatusInProgress: 1,
	domain.AssignStatusAtPickup:   1,
	domain.AssignStatusPickedUp:   2,
	domain.AssignStatusInTransit:  3,
	domain.AssignStatusArrived:    4,
	domain.AssignStatusDelivered:  5,
	domain.AssignStatusCompleted:  6,
}

func validProgressTransition(from, to string) bool {
	fromRank, okFrom := progressOrder[from]
	toRank, okTo := progressOrder[to]
	if !okFrom || !okTo {
		return false
	}
	return toRank > fromRank
}

// RecordWorkerLocation records a worker's current position on their assigned leg.
func (e *Engine) RecordWorkerLocation(ctx context.Context, p *Principal, assignmentID string,
	coordinate domain.Coordinate, sequence int, recordedAt time.Time) (any, int, error) {
	if err := e.requireRole(p, "record worker locations",
		domain.RoleCollectionProfession, domain.RoleDeliveryPartner); err != nil {
		return nil, 0, err
	}
	if err := validateCoordinate(coordinate); err != nil {
		return nil, 0, err
	}
	if sequence < 1 {
		return nil, 0, errBadRequest("invalid_sequence", "sequence must be at least 1")
	}
	if recordedAt.IsZero() {
		return nil, 0, errBadRequest("invalid_time", "recordedAt is required")
	}
	return e.mutate(ctx, "record_worker_location", "", "", p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		a := e.assignments[assignmentID]
		if a == nil {
			return nil, 0, errNotFound("assignment not found")
		}
		if a.WorkerID != p.User.UserID {
			return nil, 0, errForbidden("only the assigned worker may report their location")
		}
		// Out-of-order pings must not overwrite a newer position.
		if a.LastPing != nil && sequence <= a.LastPing.Sequence {
			return nil, 0, errConflict("stale_location", "a newer location has already been recorded")
		}
		a.LastPing = &domain.LocationPing{Coordinate: coordinate, Sequence: sequence, RecordedAt: recordedAt}
		t.saveAssignment(a)

		worker := e.users[p.User.UserID]
		worker.LatestLocation = &coordinate
		worker.LocationRecordedAt = timePtr(recordedAt)
		t.saveUser(worker)

		var subjects []string
		subjects = append(subjects, a.AssignmentID, p.User.UserID)
		for _, sampleID := range a.Samples() {
			sample := e.samples[sampleID]
			if sample == nil || sample.Terminal() {
				continue
			}
			if sample.CurrentHolderID == p.User.UserID {
				sample.LatestLocation = &coordinate
				sample.LocationRecordedAt = timePtr(recordedAt)
				t.saveSample(sample)
			}
			subjects = append(subjects, sampleID)
		}

		t.audit("record_worker_location", "assignment", a.AssignmentID, true, map[string]any{
			"coordinate": coordinate, "sequence": sequence, "recordedAt": formatTime(recordedAt),
		}, subjects...)
		t.event("worker_location", "user", p.User.UserID, map[string]any{
			"workerId": p.User.UserID, "coordinate": coordinate, "recordedAt": formatTime(recordedAt),
		}, operationsAudience()...)

		return map[string]any{
			"assignmentId": a.AssignmentID,
			"coordinate":   coordinate,
			"sequence":     sequence,
			"recordedAt":   formatTime(recordedAt),
		}, 201, nil
	})
}

// ConfirmLaboratoryReceipt completes the journey when the laboratory takes the sample in.
func (e *Engine) ConfirmLaboratoryReceipt(ctx context.Context, p *Principal, sampleID, laboratoryID string,
	receivedAt time.Time, idemKey, idemHash string) (any, int, error) {
	if err := e.requireRole(p, "confirm laboratory receipt", domain.RoleLaboratoryTeam); err != nil {
		return nil, 0, err
	}
	if idemKey == "" {
		return nil, 0, errIdempotencyRequired()
	}
	if receivedAt.IsZero() {
		return nil, 0, errBadRequest("invalid_time", "receivedAt is required")
	}
	return e.mutate(ctx, "confirm_laboratory_receipt", idemKey, idemHash, p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		sample := e.samples[sampleID]
		if sample == nil {
			return nil, 0, errNotFound("sample not found")
		}
		lab := e.locations[laboratoryID]
		if lab == nil {
			return nil, 0, errNotFound("laboratory not found")
		}
		if p.User.AssignedLocationID != laboratoryID {
			t.audit("permission_check", "sample", sampleID, false, map[string]any{
				"action": "confirm_laboratory_receipt", "reason": "wrong_laboratory_operator",
			}, sampleID, laboratoryID, p.User.UserID)
			return nil, 0, errForbiddenCode("wrong_laboratory_operator",
				"the operator is not assigned to this laboratory")
		}
		if sample.Status == domain.SampleStatusReceived {
			return map[string]any{
				"sampleId":     sample.SampleID,
				"laboratoryId": sample.ReceivedLaboratoryID,
				"status":       "received",
				"receivedAt":   formatTime(*sample.ReceivedAt),
			}, 201, nil
		}
		if !lab.FunctionActive(domain.FunctionLaboratory) {
			return nil, 0, errConflict("laboratory_unavailable", "the laboratory function is not active")
		}
		if !lab.Accepts(sample.SampleTypeID) {
			return nil, 0, errConflict("laboratory_unavailable", "the laboratory does not accept this sample type")
		}
		if !sample.Sealed {
			return nil, 0, errConflict("receipt_not_ready", "the sample has not been sealed")
		}
		if sample.CurrentHolderID != p.User.UserID {
			return nil, 0, errConflict("custody_conflict", "the receiving operator does not hold the sample")
		}
		if e.pendingHandoff(sampleID) != nil {
			return nil, 0, errConflict("pending_handoff_exists", "a handoff is still pending for this sample")
		}
		if receivedAt.After(t.now.Add(5 * time.Minute)) {
			return nil, 0, errConflict("invalid_receipt_time", "receivedAt is in the future")
		}
		// A sample received after its deadline is flagged rather than silently accepted.
		if receivedAt.After(sample.DeliveryDeadline) {
			sample.Status = domain.SampleStatusException
			sample.Exception = &domain.ExceptionInfo{
				Reason:     "delivery_deadline_exceeded",
				Kind:       "deadline",
				Detail:     "laboratory receipt occurred after the delivery deadline",
				OccurredAt: receivedAt,
				RaisedByID: p.User.UserID,
			}
			t.saveSample(sample)
			t.audit("sample_exception", "sample", sample.SampleID, true, map[string]any{
				"reason": "delivery_deadline_exceeded", "receivedAt": formatTime(receivedAt),
				"deliveryDeadline": formatTime(sample.DeliveryDeadline),
			}, sample.SampleID, sample.ActiveJourneyID, laboratoryID)
			t.event("sample_exception", "sample", sample.SampleID, map[string]any{
				"sampleId": sample.SampleID, "reason": "delivery_deadline_exceeded",
			}, append(operationsAudience(), userAudience(sample.RequesterID))...)
			return nil, 0, errConflict("delivery_deadline_exceeded",
				"the sample arrived after its delivery deadline")
		}

		sample.Status = domain.SampleStatusReceived
		sample.ReceivedLaboratoryID = laboratoryID
		sample.ReceivedAt = timePtr(receivedAt)
		sample.LatestLocation = &lab.Coordinate
		sample.LocationRecordedAt = timePtr(receivedAt)
		t.saveSample(sample)

		e.completeLaboratoryWork(t, sample, laboratoryID, receivedAt)

		t.audit("confirm_laboratory_receipt", "sample", sample.SampleID, true, map[string]any{
			"laboratoryId": laboratoryID, "receivedAt": formatTime(receivedAt),
			"status": "received",
		}, sample.SampleID, laboratoryID, sample.ActiveJourneyID, p.User.UserID)
		t.event("sample_received", "sample", sample.SampleID, map[string]any{
			"sampleId": sample.SampleID, "laboratoryId": laboratoryID,
		}, append(operationsAudience(), userAudience(sample.RequesterID))...)

		return map[string]any{
			"sampleId":     sample.SampleID,
			"laboratoryId": laboratoryID,
			"status":       "received",
			"receivedAt":   formatTime(receivedAt),
		}, 201, nil
	})
}

// completeLaboratoryWork closes the laboratory assignment and the journey, releasing capacity.
func (e *Engine) completeLaboratoryWork(t *txn, sample *domain.Sample, laboratoryID string, at time.Time) {
	journey := e.journeys[sample.ActiveJourneyID]
	if journey == nil {
		return
	}
	for _, id := range journey.AssignmentIDs {
		a := e.assignments[id]
		if a == nil || a.Terminal() {
			continue
		}
		a.Status = domain.AssignStatusCompleted
		a.CompletedAt = timePtr(at)
		t.saveAssignment(a)
		sample.CompletedLegIDs = appendUnique(sample.CompletedLegIDs, a.AssignmentID)
	}
	for i := range journey.Stops {
		if journey.Stops[i].CompletedAt == nil {
			journey.Stops[i].CompletedAt = timePtr(at)
		}
	}
	journey.Status = domain.JourneyStatusCompleted
	e.releaseJourneyReservations(t, journey)
	t.saveJourney(journey)
	t.audit("complete_journey", "journey", journey.JourneyID, true, map[string]any{
		"sampleIds": journey.SampleIDs, "laboratoryId": laboratoryID, "completedAt": formatTime(at),
	}, journey.JourneyID, sample.SampleID)
}

// RecordLaboratoryException records that a sample could not be accepted normally.
func (e *Engine) RecordLaboratoryException(ctx context.Context, p *Principal, sampleID, laboratoryID,
	reason string, observedAt time.Time, idemKey, idemHash string) (any, int, error) {
	if err := e.requireRole(p, "record laboratory exceptions", domain.RoleLaboratoryTeam); err != nil {
		return nil, 0, err
	}
	if idemKey == "" {
		return nil, 0, errIdempotencyRequired()
	}
	if reason == "" {
		return nil, 0, errBadRequest("invalid_json", "reason is required")
	}
	if observedAt.IsZero() {
		return nil, 0, errBadRequest("invalid_time", "observedAt is required")
	}
	return e.mutate(ctx, "record_laboratory_exception", idemKey, idemHash, p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		sample := e.samples[sampleID]
		if sample == nil {
			return nil, 0, errNotFound("sample not found")
		}
		lab := e.locations[laboratoryID]
		if lab == nil {
			return nil, 0, errNotFound("laboratory not found")
		}
		if p.User.AssignedLocationID != laboratoryID {
			return nil, 0, errForbiddenCode("wrong_laboratory_operator",
				"the operator is not assigned to this laboratory")
		}
		if !lab.Functions.Laboratory {
			return nil, 0, errConflict("laboratory_not_ready", "location does not provide the laboratory function")
		}
		if sample.TargetLaboratoryID != "" && sample.TargetLaboratoryID != laboratoryID {
			return nil, 0, errConflict("wrong_laboratory", "the sample is not routed to this laboratory")
		}
		if observedAt.After(t.now.Add(5 * time.Minute)) {
			return nil, 0, errConflict("invalid_exception_time", "observedAt is in the future")
		}

		exceptionID := newUUID()
		sample.Status = domain.SampleStatusException
		sample.Exception = &domain.ExceptionInfo{
			Reason:     reason,
			Kind:       "laboratory",
			Detail:     "laboratory could not accept the sample normally",
			OccurredAt: observedAt,
			RaisedByID: p.User.UserID,
		}
		t.saveSample(sample)

		if journey := e.journeys[sample.ActiveJourneyID]; journey != nil {
			journey.Status = domain.JourneyStatusException
			e.releaseJourneyReservations(t, journey)
			t.saveJourney(journey)
		}

		t.audit("record_laboratory_exception", "sample", sample.SampleID, true, map[string]any{
			"exceptionId": exceptionID, "laboratoryId": laboratoryID, "reason": reason,
			"observedAt": formatTime(observedAt),
		}, sample.SampleID, laboratoryID, sample.ActiveJourneyID, p.User.UserID)
		t.event("sample_exception", "sample", sample.SampleID, map[string]any{
			"sampleId": sample.SampleID, "reason": reason, "laboratoryId": laboratoryID,
		}, append(operationsAudience(), userAudience(sample.RequesterID))...)

		return map[string]any{
			"exceptionId": exceptionID,
			"sampleId":    sample.SampleID,
			"status":      "exception",
			"reason":      reason,
		}, 201, nil
	})
}
