// checkPlanVersion enforces the journey plan-version check so that an outdated update
// cannot overwrite a newer one.
func checkPlanVersion(journey *domain.Journey, expected int) error {
	if expected < 1 {
		return errBadRequest("invalid_plan_version", "expectedPlanVersion must be at least 1")
	}
	if expected != journey.PlanVersion {
		return errConflict("stale_plan", "the plan has already moved to a newer version")
	}
	return nil
}

func requireActivePlan(journey *domain.Journey) error {
	if !journey.Unfinished() {
		return errConflict("inactive_plan", "journey is no longer active")
	}
	return nil
}

// CancelJourney cancels unfinished work on a journey and releases its capacity.
func (e *Engine) CancelJourney(ctx context.Context, p *Principal, journeyID string, expectedPlanVersion int,
	reason, idemKey, idemHash string) (any, int, error) {
	if err := e.requireRole(p, "cancel journeys", domain.RoleDispatcher, domain.RoleAdministrator); err != nil {
		return nil, 0, err
	}
	if idemKey == "" {
		return nil, 0, errIdempotencyRequired()
	}
	return e.mutate(ctx, "cancel_journey", idemKey, idemHash, p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		journey := e.journeys[journeyID]
		if journey == nil {
			return nil, 0, errNotFound("journey not found")
		}
		if err := checkPlanVersion(journey, expectedPlanVersion); err != nil {
			return nil, 0, err
		}
		if err := requireActivePlan(journey); err != nil {
			return nil, 0, err
		}

		e.cancelUnfinishedWork(t, journey, "journey_cancelled")
		journey.Status = domain.JourneyStatusCancelled
		journey.PlanVersion++
		e.releaseJourneyReservations(t, journey)
		t.saveJourney(journey)

		for _, sampleID := range journey.SampleIDs {
			sample := e.samples[sampleID]
			if sample == nil || sample.Terminal() {
				continue
			}
			// Custody is never rewritten: a held sample stays with its holder.
			if sample.CurrentHolderID == "" {
				sample.Status = domain.SampleStatusCancelled
			}
			sample.ActiveJourneyID = ""
			t.saveSample(sample)
			t.audit("cancel_journey", "sample", sampleID, true, map[string]any{
				"journeyId": journeyID, "reason": reason, "status": sample.Status,
			}, sampleID, journeyID)
		}

		t.audit("cancel_journey", "journey", journeyID, true, map[string]any{
			"reason": reason, "planVersion": journey.PlanVersion, "sampleIds": journey.SampleIDs,
		}, journeyID)
		t.event("journey_cancelled", "journey", journeyID, map[string]any{
			"journeyId": journeyID, "sampleIds": journey.SampleIDs,
		}, operationsAudience()...)

		return map[string]any{
			"journeyId": journeyID,
			"status":    "cancelled",
			"sampleIds": stringsOrEmpty(journey.SampleIDs),
		}, 201, nil
	})
}

// cancelUnfinishedWork cancels assignments that have not been completed, leaving completed
// work and confirmed custody untouched.
func (e *Engine) cancelUnfinishedWork(t *txn, journey *domain.Journey, reason string) {
	for _, id := range journey.AssignmentIDs {
		a := e.assignments[id]
		if a == nil || a.Terminal() {
			continue
		}
		previous := a.Status
		a.Status = domain.AssignStatusCancelled
		t.saveAssignment(a)
		t.audit("cancel_assignment", "assignment", a.AssignmentID, true, map[string]any{
			"previousStatus": previous, "reason": reason, "journeyId": journey.JourneyID,
		}, a.AssignmentID, a.SampleID, journey.JourneyID)
	}
}

// SplitJourney moves some samples of a batched journey onto their own journey.
func (e *Engine) SplitJourney(ctx context.Context, p *Principal, journeyID string, expectedPlanVersion int,
	sampleIDs []string, idemKey, idemHash string) (any, int, error) {
	if err := e.requireRole(p, "split journeys", domain.RoleDispatcher, domain.RoleAdministrator); err != nil {
		return nil, 0, err
	}
	if idemKey == "" {
		return nil, 0, errIdempotencyRequired()
	}
	if len(sampleIDs) == 0 {
		return nil, 0, errConflict("invalid_split", "at least one sample must be split out")
	}
	return e.mutate(ctx, "split_journey", idemKey, idemHash, p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		journey := e.journeys[journeyID]
		if journey == nil {
			return nil, 0, errNotFound("journey not found")
		}
		if err := checkPlanVersion(journey, expectedPlanVersion); err != nil {
			return nil, 0, err
		}
		if err := requireActivePlan(journey); err != nil {
			return nil, 0, err
		}
		for _, id := range sampleIDs {
			if !containsString(journey.SampleIDs, id) {
				return nil, 0, errConflict("invalid_split", "sample is not part of this journey")
			}
		}
		if len(sampleIDs) >= len(journey.SampleIDs) {
			return nil, 0, errConflict("invalid_split", "at least one sample must remain on the journey")
		}
		// Work already in progress for those samples must not be rewritten.
		if e.workStarted(journey, sampleIDs) {
			return nil, 0, errConflict("split_in_progress", "work for these samples has already started")
		}

		remaining := []string{}
		for _, id := range journey.SampleIDs {
			if !containsString(sampleIDs, id) {
				remaining = append(remaining, id)
			}
		}

		split, err := e.rebuildJourneyFor(t, journey, sampleIDs, journey.JourneyID)
		if err != nil {
			return nil, 0, err
		}
		if err := e.reshapeJourney(t, journey, remaining); err != nil {
			return nil, 0, err
		}

		t.audit("split_journey", "journey", journey.JourneyID, true, map[string]any{
			"splitJourneyId": split.JourneyID, "movedSampleIds": sampleIDs,
			"remainingSampleIds": remaining, "planVersion": journey.PlanVersion,
		}, journey.JourneyID, split.JourneyID)
		t.event("journey_split", "journey", journey.JourneyID, map[string]any{
			"journeyId": journey.JourneyID, "splitJourneyId": split.JourneyID,
		}, operationsAudience()...)

		return map[string]any{
			"journey":      e.journeyPlanView(journey, nil),
			"splitJourney": e.journeyPlanView(split, nil),
		}, 201, nil
	})
}

// workStarted reports whether any assignment covering the given samples is under way.
func (e *Engine) workStarted(journey *domain.Journey, sampleIDs []string) bool {
	for _, id := range journey.AssignmentIDs {
		a := e.assignments[id]
		if a == nil {
			continue
		}
		if !a.InProgress() && a.Status != domain.AssignStatusCompleted {
			continue
		}
		for _, sampleID := range sampleIDs {
			if containsString(a.Samples(), sampleID) {
				return true
			}
		}
	}
	return false
}

// MergeJourneys combines compatible source journeys into the target journey.
func (e *Engine) MergeJourneys(ctx context.Context, p *Principal, targetJourneyID string, expectedPlanVersion int,
	sourceJourneyIDs []string, idemKey, idemHash string) (any, int, error) {
	if err := e.requireRole(p, "merge journeys", domain.RoleDispatcher, domain.RoleAdministrator); err != nil {
		return nil, 0, err
	}
	if idemKey == "" {
		return nil, 0, errIdempotencyRequired()
	}
	if len(sourceJourneyIDs) == 0 {
		return nil, 0, errConflict("invalid_merge", "at least one source journey is required")
	}
	return e.mutate(ctx, "merge_journeys", idemKey, idemHash, p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		target := e.journeys[targetJourneyID]
		if target == nil {
			return nil, 0, errNotFound("journey not found")
		}
		if err := checkPlanVersion(target, expectedPlanVersion); err != nil {
			return nil, 0, err
		}
		if err := requireActivePlan(target); err != nil {
			return nil, 0, err
		}

		merged := append([]string{}, target.SampleIDs...)
		var sources []*domain.Journey
		for _, id := range sourceJourneyIDs {
			source := e.journeys[id]
			if source == nil {
				return nil, 0, errNotFound("source journey not found")
			}
			if source.JourneyID == target.JourneyID {
				return nil, 0, errConflict("invalid_merge", "a journey cannot be merged into itself")
			}
			if !source.Unfinished() {
				return nil, 0, errConflict("invalid_merge", "source journey is no longer active")
			}
			// Merging must not rewrite work that has already started.
			if e.workStarted(source, source.SampleIDs) {
				return nil, 0, errConflict("partial_journey_merge", "source journey has work in progress")
			}
			sources = append(sources, source)
			for _, sampleID := range source.SampleIDs {
				merged = appendUnique(merged, sampleID)
			}
		}
		if err := e.validateBatch(merged, target.LaboratoryID); err != nil {
			return nil, 0, err
		}
		if err := e.reshapeJourney(t, target, merged); err != nil {
			return nil, 0, err
		}
		target.RouteMode = domain.RouteBatched
		t.saveJourney(target)

		for _, source := range sources {
			e.cancelUnfinishedWork(t, source, "merged_into_"+target.JourneyID)
			source.Status = domain.JourneyStatusReplaced
			source.PlanVersion++
			e.releaseJourneyReservations(t, source)
			t.saveJourney(source)
			t.audit("merge_journeys", "journey", source.JourneyID, true, map[string]any{
				"mergedInto": target.JourneyID, "status": source.Status,
			}, source.JourneyID, target.JourneyID)
		}
		for _, sampleID := range merged {
			if sample := e.samples[sampleID]; sample != nil {
				sample.ActiveJourneyID = target.JourneyID
				t.saveSample(sample)
			}
		}

		t.audit("merge_journeys", "journey", target.JourneyID, true, map[string]any{
			"sourceJourneyIds": sourceJourneyIDs, "sampleIds": merged,
			"planVersion": target.PlanVersion, "routeMode": string(target.RouteMode),
		}, append([]string{target.JourneyID}, sourceJourneyIDs...)...)
		t.event("journeys_merged", "journey", target.JourneyID, map[string]any{
			"journeyId": target.JourneyID, "sourceJourneyIds": sourceJourneyIDs,
		}, operationsAudience()...)

		return e.journeyPlanView(target, nil), 201, nil
	})
}

// validateBatch enforces the rules that let samples travel together.
func (e *Engine) validateBatch(sampleIDs []string, laboratoryID string) error {
	var samples []*domain.Sample
	for _, id := range sampleIDs {
		sample := e.samples[id]
		if sample == nil {
			return errConflict("invalid_batch", "unknown sample in batch")
		}
		samples = append(samples, sample)
	}
	for i, a := range samples {
		typeA := e.sampleTypes[a.SampleTypeID]
		// A time-critical sample must not wait to be combined into a batch.
		if typeA != nil && !typeA.BatchingAllowed && len(samples) > 1 {
			return errConflict("pulse_no_batch",
				"sample type "+typeA.Name+" must be routed without batching delay")
		}
		for j, b := range samples {
			if i == j {
				continue
			}
			if containsString(a.IncompatibleSampleTypes, b.SampleTypeID) ||
				containsString(b.IncompatibleSampleTypes, a.SampleTypeID) {
				return errConflict("incompatible_batch", "these sample types may not share a container")
			}
			typeB := e.sampleTypes[b.SampleTypeID]
			if typeA != nil && typeB != nil {
				if containsString(typeA.IncompatibleSampleTypes, typeB.SampleTypeID) {
					return errConflict("incompatible_batch", "these sample types may not share a container")
				}
				if typeA.RequiresCooledRoute != typeB.RequiresCooledRoute {
					return errConflict("incompatible_batch",
						"cooled and non-cooled samples may not share transport")
				}
			}
			if a.ContainerType != b.ContainerType {
				return errConflict("incompatible_batch", "container requirements differ")
			}
			// The batch temperature band must be satisfiable for every member.
			if a.TemperatureMinC > b.TemperatureMaxC || b.TemperatureMinC > a.TemperatureMaxC {
				return errConflict("incompatible_batch", "temperature requirements do not overlap")
			}
		}
		if laboratoryID != "" {
			lab := e.locations[laboratoryID]
			if lab == nil || !lab.FunctionActive(domain.FunctionLaboratory) || !lab.Accepts(a.SampleTypeID) {
				return errConflict("invalid_destination", "the laboratory does not accept every sample in the batch")
			}
		}
	}
	return nil
}

// reshapeJourney replans a journey for a new sample set, keeping completed work intact.
func (e *Engine) reshapeJourney(t *txn, journey *domain.Journey, sampleIDs []string) error {
	if len(sampleIDs) == 0 {
		return errConflict("invalid_plan", "a journey must carry at least one sample")
	}
	lead := e.samples[sampleIDs[0]]
	if lead == nil {
		return errConflict("invalid_plan", "unknown sample")
	}
	if err := e.validateBatch(sampleIDs, ""); err != nil {
		return err
	}

	deadline := lead.DeliveryDeadline
	for _, id := range sampleIDs {
		if sample := e.samples[id]; sample != nil && sample.DeliveryDeadline.Before(deadline) {
			deadline = sample.DeliveryDeadline
		}
	}

	sampleType := e.sampleTypes[lead.SampleTypeID]
	// Replanning starts from where the sample actually is now.
	origin, originType, originNode := e.currentPosition(lead)
	collectAt := e.replanCollectAt(t, lead)

	// The pools held by the old shape are freed before the new shape reserves.
	e.releaseJourneyReservations(t, journey)

	plan, reason := e.planRoute(routeRequest{
		Origin:       origin,
		OriginType:   originType,
		OriginNodeID: originNode,
		SampleType:   sampleType,
		Cooled:       sampleType != nil && sampleType.RequiresCooledRoute,
		CollectAt:    collectAt,
		Deadline:     deadline,
		PreSealed:    lead.Sealed,
	})
	if plan == nil {
		// Reject the change and keep the current plan in place.
		e.restoreReservations(t, journey)
		return planFailure(reason)
	}

	e.cancelUnfinishedWork(t, journey, "replanned")
	journey.Reservations = nil
	journey.SampleIDs = sampleIDs
	journey.Stops = nil
	journey.AssignmentIDs = nil
	journey.LaboratoryID = plan.LaboratoryID
	journey.EstimatedDeliveryAt = timePtr(plan.ArrivalAt)
	journey.TotalCostUnits = plan.TotalCost
	journey.PlanVersion++
	journey.Valid = true
	if len(sampleIDs) > 1 {
		journey.RouteMode = domain.RouteBatched
	} else {
		journey.RouteMode = routeModeFor(plan)
	}

	if err := e.materialisePlan(t, journey, plan, sampleIDs); err != nil {
		return err
	}
	for _, id := range sampleIDs {
		if sample := e.samples[id]; sample != nil {
			sample.ActiveJourneyID = journey.JourneyID
			sample.TargetLaboratoryID = plan.LaboratoryID
			t.saveSample(sample)
		}
	}
	t.saveJourney(journey)
	return nil
}

// restoreReservations re-applies the holds of a journey after a rejected change.
func (e *Engine) restoreReservations(t *txn, journey *domain.Journey) {
	for i := range journey.Reservations {
		r := &journey.Reservations[i]
		if !r.Released {
			continue
		}
		if err := e.applyReservation(*r); err == nil {
			r.Released = false
			switch r.ResourceKind {
			case "location":
				if loc := e.locations[r.ResourceID]; loc != nil {
					t.saveLocation(loc)
				}
			case "connection":
				if conn := e.connections[r.ResourceID]; conn != nil {
					t.saveConnection(conn)
				}
			}
		}
	}
	t.saveJourney(journey)
}

// planFailure maps a routing reason onto the contract error code.
func planFailure(reason string) error {
	switch reason {
	case ReasonDeadline:
		return errConflict("delivery_deadline_exceeded", "no plan can meet the delivery deadline")
	case ReasonNoCapacity:
		return errConflict("capacity_exhausted", "required capacity is not available")
	case ReasonNoLaboratory:
		return errConflict("invalid_destination", "no active laboratory accepts this sample type")
	case ReasonHandlingRules:
		return errConflict("incompatible_batch", "handling rules cannot be satisfied")
	default:
		return errConflict("no_valid_route", "no valid route is available")
	}
}

// currentPosition returns where a sample is now, used as the origin when replanning.
func (e *Engine) currentPosition(sample *domain.Sample) (domain.Coordinate, domain.OriginType, string) {
	if sample.CurrentHolderID != "" {
		// A sample already in custody continues from the last site it reached.
		if node := e.lastCompletedLocation(sample); node != "" {
			if loc := e.locations[node]; loc != nil {
				return loc.Coordinate, domain.OriginNode, node
			}
		}
	}
	if sample.OriginNodeID != "" {
		if loc := e.locations[sample.OriginNodeID]; loc != nil {
			return loc.Coordinate, domain.OriginNode, sample.OriginNodeID
		}
	}
	return sample.Origin, sample.OriginType, ""
}

// lastCompletedLocation returns the last site whose custody step finished.
func (e *Engine) lastCompletedLocation(sample *domain.Sample) string {
	var best *domain.Assignment
	for _, id := range sample.CompletedLegIDs {
		a := e.assignments[id]
		if a == nil {
			continue
		}
		if best == nil || a.Sequence > best.Sequence {
			best = a
		}
	}
	if best == nil {
		return ""
	}
	return assignmentExitLocation(best)
}

func (e *Engine) replanCollectAt(t *txn, sample *domain.Sample) time.Time {
	if sample.Sealed {
		if t.now.After(sample.EarliestCollectionAt) {
			return t.now
		}
		return sample.EarliestCollectionAt
	}
	if t.now.After(sample.EarliestCollectionAt) {
		return t.now
	}
	return sample.EarliestCollectionAt
}

// materialisePlan creates stops, assignments and reservations for an existing journey.
func (e *Engine) materialisePlan(t *txn, journey *domain.Journey, plan *routePlan, sampleIDs []string) error {
	lead := e.samples[sampleIDs[0]]
	sampleType := e.sampleTypes[lead.SampleTypeID]
	cooled := sampleType != nil && sampleType.RequiresCooledRoute

	for _, sampleID := range sampleIDs {
		sample := e.samples[sampleID]
		if sample == nil {
			continue
		}
		if err := e.reserveForJourney(t, journey, sample, plan); err != nil {
			return err
		}
	}

	sequence := 0
	addStop := func(locationID string, stopType domain.StopType, at time.Time) *domain.Stop {
		sequence++
		loc := e.locations[locationID]
		coord := domain.Coordinate{}
		dwell := 0
		if loc != nil {
			coord = loc.Coordinate
			dwell = loc.HandlingMinutes
		}
		journey.Stops = append(journey.Stops, domain.Stop{
			StopID:       newUUID(),
			LocationID:   locationID,
			StopType:     stopType,
			Sequence:     sequence,
			EstimatedAt:  at,
			DwellMinutes: dwell,
			Coordinate:   coord,
		})
		return &journey.Stops[len(journey.Stops)-1]
	}

	var created []*domain.Assignment
	seq := 0
	if !lead.Sealed {
		qualification := ""
		if sampleType != nil && sampleType.QualifiedCollectorRequired {
			qualification = sampleType.RequiredQualification
		}
		seq++
		created = append(created, &domain.Assignment{
			AssignmentID:          newUUID(),
			Kind:                  domain.AssignmentCollection,
			JourneyID:             journey.JourneyID,
			SampleID:              lead.SampleID,
			SampleIDs:             sampleIDs,
			Sequence:              seq,
			Status:                domain.AssignStatusPending,
			ToLocationID:          plan.EntryNodeID,
			RequiredRole:          domain.RoleCollectionProfession,
			RequiredQualification: qualification,
			Cooled:                cooled,
			DeclinedByIDs:         []string{},
			CreatedAt:             t.now,
		})
	}
	entryStop := addStop(plan.EntryNodeID, domain.StopPickup, plan.NodeArrival[0])
	if len(created) == 1 {
		created[0].DropoffStopID = entryStop.StopID
	}

	for i, conn := range plan.Connections {
		seq++
		fromStop := journey.Stops[len(journey.Stops)-1]
		stopType := domain.StopHandoff
		if i == len(plan.Connections)-1 {
			stopType = domain.StopDelivery
		}
		toStop := addStop(conn.ToLocationID, stopType, plan.NodeArrival[i+1])
		created = append(created, &domain.Assignment{
			AssignmentID:   newUUID(),
			Kind:           domain.AssignmentTransport,
			JourneyID:      journey.JourneyID,
			SampleID:       lead.SampleID,
			SampleIDs:      sampleIDs,
			Sequence:       seq,
			Status:         domain.AssignStatusPending,
			FromLocationID: conn.FromLocationID,
			ToLocationID:   conn.ToLocationID,
			ConnectionID:   conn.ConnectionID,
			RequiredRole:   domain.RoleDeliveryPartner,
			Cooled:         cooled,
			PickupStopID:   fromStop.StopID,
			DropoffStopID:  toStop.StopID,
			DeclinedByIDs:  []string{},
			CreatedAt:      t.now,
		})
	}
	for i, locationID := range plan.Path {
		if locationID == plan.LaboratoryID {
			continue
		}
		seq++
		created = append(created, &domain.Assignment{
			AssignmentID:   newUUID(),
			Kind:           domain.AssignmentNode,
			JourneyID:      journey.JourneyID,
			SampleID:       lead.SampleID,
			SampleIDs:      sampleIDs,
			Sequence:       seq,
			Status:         domain.AssignStatusPending,
			NodeID:         locationID,
			FromLocationID: previousLocation(plan.Path, i),
			ToLocationID:   nextLocation(plan.Path, i),
			RequiredRole:   domain.RoleNodeHandler,
			Cooled:         cooled,
			DeclinedByIDs:  []string{},
			CreatedAt:      t.now,
		})
	}
	seq++
	created = append(created, &domain.Assignment{
		AssignmentID:  newUUID(),
		Kind:          domain.AssignmentLaboratory,
		JourneyID:     journey.JourneyID,
		SampleID:      lead.SampleID,
		SampleIDs:     sampleIDs,
		Sequence:      seq,
		Status:        domain.AssignStatusPending,
		LaboratoryID:  plan.LaboratoryID,
		RequiredRole:  domain.RoleLaboratoryTeam,
		Cooled:        cooled,
		DeclinedByIDs: []string{},
		CreatedAt:     t.now,
	})

	for _, a := range created {
		e.assignments[a.AssignmentID] = a
		journey.AssignmentIDs = append(journey.AssignmentIDs, a.AssignmentID)
		t.saveAssignment(a)
	}
	for _, a := range created {
		e.offerAssignment(t, a)
	}
	return nil
}

// rebuildJourneyFor creates a new journey carrying the given samples.
func (e *Engine) rebuildJourneyFor(t *txn, parent *domain.Journey, sampleIDs []string,
	parentID string) (*domain.Journey, error) {
	lead := e.samples[sampleIDs[0]]
	if lead == nil {
		return nil, errConflict("invalid_split", "unknown sample")
	}
	journey := &domain.Journey{
		JourneyID:       newUUID(),
		ParentJourneyID: parentID,
		PlanVersion:     1,
		Status:          domain.JourneyStatusPlanned,
		Valid:           true,
		CreatedAt:       t.now,
	}
	e.journeys[journey.JourneyID] = journey
	if err := e.reshapeJourney(t, journey, sampleIDs); err != nil {
		delete(e.journeys, journey.JourneyID)
		return nil, err
	}
	// reshapeJourney increments the version; a brand new journey starts at 1.
	journey.PlanVersion = 1
	t.saveJourney(journey)
	return journey, nil
}

// RerouteJourney replaces the unfinished part of a journey with a new plan.
func (e *Engine) RerouteJourney(ctx context.Context, p *Principal, journeyID string, expectedPlanVersion int,
	reason, idemKey, idemHash string) (any, int, error) {
	if err := e.requireRole(p, "reroute journeys", domain.RoleDispatcher, domain.RoleAdministrator); err != nil {
		return nil, 0, err
	}
	if idemKey == "" {
		return nil, 0, errIdempotencyRequired()
	}
	return e.mutate(ctx, "reroute_journey", idemKey, idemHash, p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		journey := e.journeys[journeyID]
		if journey == nil {
			return nil, 0, errNotFound("journey not found")
		}
		if err := checkPlanVersion(journey, expectedPlanVersion); err != nil {
			return nil, 0, err
		}
		if err := requireActivePlan(journey); err != nil {
			return nil, 0, err
		}
		status, replacement := e.replanJourney(t, journey, reason, nil, nil)
		out := map[string]any{"journeyId": journeyID, "replanStatus": status}
		if replacement != nil {
			out["replacementPlanId"] = replacement.JourneyID
			out["replacementJourney"] = e.journeyPlanView(replacement, nil)
		}
		t.audit("reroute_journey", "journey", journeyID, true, map[string]any{
			"reason": reason, "replanStatus": status,
		}, journeyID)
		return out, 201, nil
	})
}

// replanJourney builds a single active replacement plan for unfinished work.
//
// Completed assignments, stops and handoffs are preserved and the current holder is never
// changed. When no valid route can meet the deadline the sample is marked expired.
func (e *Engine) replanJourney(t *txn, journey *domain.Journey, reason string,
	excludedLocations, excludedConnections map[string]bool) (string, *domain.Journey) {
	if journey.ReplacementID != "" {
		if existing := e.journeys[journey.ReplacementID]; existing != nil && existing.Unfinished() {
			// Only one active replacement plan is allowed per journey.
			return "replaced", existing
		}
	}

	lead := e.samples[journey.SampleIDs[0]]
	if lead == nil || lead.Terminal() {
		return "not_required", nil
	}

	origin, originType, originNode := e.currentPosition(lead)
	sampleType := e.sampleTypes[lead.SampleTypeID]
	deadline := lead.DeliveryDeadline
	for _, id := range journey.SampleIDs {
		if sample := e.samples[id]; sample != nil && sample.DeliveryDeadline.Before(deadline) {
			deadline = sample.DeliveryDeadline
		}
	}

	plan, planReason := e.planRoute(routeRequest{
		Origin:              origin,
		OriginType:          originType,
		OriginNodeID:        originNode,
		SampleType:          sampleType,
		Cooled:              sampleType != nil && sampleType.RequiresCooledRoute,
		CollectAt:           e.replanCollectAt(t, lead),
		Deadline:            deadline,
		PreSealed:           lead.Sealed,
		ExcludedLocations:   excludedLocations,
		ExcludedConnections: excludedConnections,
	})

	if plan == nil {
		if planReason == ReasonDeadline || planReason == ReasonNoRoute ||
			planReason == ReasonOutsideCoverage || planReason == ReasonNoLaboratory {
			return e.expireJourney(t, journey, planReason), nil
		}
		// Capacity or handling problems are recoverable: flag them as an exception.
		return e.exceptionJourney(t, journey, planReason), nil
	}

	replacement := &domain.Journey{
		JourneyID:         newUUID(),
		ParentJourneyID:   journey.JourneyID,
		ReplacesJourneyID: journey.JourneyID,
		PlanVersion:       1,
		Status:            domain.JourneyStatusPlanned,
		SampleIDs:         append([]string{}, journey.SampleIDs...),
		LaboratoryID:      plan.LaboratoryID,
		EstimatedDeliveryAt: timePtr(plan.ArrivalAt),
		TotalCostUnits:      plan.TotalCost,
		RouteMode:           routeModeFor(plan),
		Valid:               true,
		CreatedAt:           t.now,
	}
	if len(replacement.SampleIDs) > 1 {
		replacement.RouteMode = domain.RouteBatched
	}
	e.journeys[replacement.JourneyID] = replacement

	// Unfinished work on the old plan is cancelled; completed work stays as it is.
	e.cancelUnfinishedWork(t, journey, "replanned:"+reason)
	e.releaseJourneyReservations(t, journey)
	if err := e.materialisePlan(t, replacement, plan, replacement.SampleIDs); err != nil {
		delete(e.journeys, replacement.JourneyID)
		e.restoreReservations(t, journey)
		return e.exceptionJourney(t, journey, ReasonNoCapacity), nil
	}

	journey.Status = domain.JourneyStatusReplaced
	journey.ReplacementID = replacement.JourneyID
	journey.PlanVersion++
	t.saveJourney(journey)
	t.saveJourney(replacement)

	for _, id := range replacement.SampleIDs {
		sample := e.samples[id]
		if sample == nil {
			continue
		}
		sample.ActiveJourneyID = replacement.JourneyID
		sample.TargetLaboratoryID = plan.LaboratoryID
		t.saveSample(sample)
		t.audit("replan_sample", "sample", sample.SampleID, true, map[string]any{
			"previousJourneyId": journey.JourneyID, "journeyId": replacement.JourneyID,
			"reason": reason, "currentHolderId": sample.CurrentHolderID,
		}, sample.SampleID, journey.JourneyID, replacement.JourneyID)
	}
	t.event("journey_replanned", "journey", replacement.JourneyID, map[string]any{
		"journeyId": replacement.JourneyID, "replaces": journey.JourneyID,
	}, operationsAudience()...)
	return "replaced", replacement
}

func (e *Engine) expireJourney(t *txn, journey *domain.Journey, reason string) string {
	e.cancelUnfinishedWork(t, journey, "expired:"+reason)
	journey.Status = domain.JourneyStatusExpired
	journey.PlanVersion++
	journey.Valid = false
	e.releaseJourneyReservations(t, journey)
	t.saveJourney(journey)
	for _, id := range journey.SampleIDs {
		sample := e.samples[id]
		if sample == nil || sample.Terminal() {
			continue
		}
		sample.Status = domain.SampleStatusExpired
		sample.Exception = &domain.ExceptionInfo{
			Reason:     "deadline_unreachable",
			Kind:       "deadline",
			Detail:     "no valid route can meet the delivery deadline (" + reason + ")",
			OccurredAt: t.now,
		}
		t.saveSample(sample)
		t.audit("sample_expired", "sample", sample.SampleID, true, map[string]any{
			"journeyId": journey.JourneyID, "reason": reason,
		}, sample.SampleID, journey.JourneyID)
		t.event("sample_expired", "sample", sample.SampleID, map[string]any{
			"sampleId": sample.SampleID, "reason": reason,
		}, append(operationsAudience(), userAudience(sample.RequesterID))...)
	}
	return "expired"
}

func (e *Engine) exceptionJourney(t *txn, journey *domain.Journey, reason string) string {
	journey.Status = domain.JourneyStatusException
	journey.PlanVersion++
	journey.Valid = false
	t.saveJourney(journey)
	for _, id := range journey.SampleIDs {
		sample := e.samples[id]
		if sample == nil || sample.Terminal() {
			continue
		}
		sample.Status = domain.SampleStatusException
		sample.Exception = &domain.ExceptionInfo{
			Reason:     reason,
			Kind:       "replan",
			Detail:     "replanning could not produce a valid plan",
			OccurredAt: t.now,
		}
		t.saveSample(sample)
		t.audit("sample_exception", "sample", sample.SampleID, true, map[string]any{
			"journeyId": journey.JourneyID, "reason": reason,
		}, sample.SampleID, journey.JourneyID)
		t.event("sample_exception", "sample", sample.SampleID, map[string]any{
			"sampleId": sample.SampleID, "reason": reason,
		}, append(operationsAudience(), userAudience(sample.RequesterID))...)
	}
	return "exception"
}

// ReportDisruption marks a resource unavailable and replans the work that depended on it.
func (e *Engine) ReportDisruption(ctx context.Context, p *Principal, resourceType, resourceID, reason string,
	occurredAt time.Time, idemKey, idemHash string) (any, int, error) {
	if err := e.requireRole(p, "report disruptions", domain.RoleDispatcher, domain.RoleAdministrator); err != nil {
		return nil, 0, err
	}
	if idemKey == "" {
		return nil, 0, errIdempotencyRequired()
	}
	if !validResourceType(resourceType) {
		return nil, 0, errBadRequest("invalid_resource_type", "unknown resourceType")
	}
	if occurredAt.IsZero() {
		return nil, 0, errBadRequest("invalid_time", "occurredAt is required")
	}
	return e.mutate(ctx, "report_disruption", idemKey, idemHash, p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole

		excludedLocations := map[string]bool{}
		excludedConnections := map[string]bool{}
		var affectedJourneys []*domain.Journey

		switch resourceType {
		case "location", "node", "laboratory":
			loc := e.locations[resourceID]
			if loc == nil {
				return nil, 0, errNotFound("location not found")
			}
			excludedLocations[resourceID] = true
			loc.Active = false
			t.saveLocation(loc)
			e.markNetworkChanged(t)
			affectedJourneys = e.journeysUsingLocation(resourceID)
		case "connection", "route":
			conn := e.connections[resourceID]
			if conn == nil {
				return nil, 0, errNotFound("connection not found")
			}
			excludedConnections[resourceID] = true
			conn.Active = false
			t.saveConnection(conn)
			e.markNetworkChanged(t)
			affectedJourneys = e.journeysUsingConnection(resourceID)
		case "worker":
			worker := e.users[resourceID]
			if worker == nil {
				return nil, 0, errNotFound("worker not found")
			}
			worker.Available = false
			t.saveUser(worker)
			affectedJourneys = e.journeysWithWorker(resourceID)
		case "capacity":
			if loc := e.locations[resourceID]; loc != nil {
				excludedLocations[resourceID] = true
				affectedJourneys = e.journeysUsingLocation(resourceID)
			} else if conn := e.connections[resourceID]; conn != nil {
				excludedConnections[resourceID] = true
				affectedJourneys = e.journeysUsingConnection(resourceID)
			} else {
				return nil, 0, errNotFound("capacity pool not found")
			}
		}

		disruption := &domain.Disruption{
			DisruptionID:       newUUID(),
			ResourceType:       resourceType,
			ResourceID:         resourceID,
			Reason:             reason,
			OccurredAt:         occurredAt,
			ReportedByID:       p.User.UserID,
			AffectedSampleIDs:  []string{},
			ReplacementPlanIDs: []string{},
			ReplanStatus:       "not_required",
			CreatedAt:          t.now,
		}

		statuses := map[string]bool{}
		for _, journey := range affectedJourneys {
			for _, id := range journey.SampleIDs {
				disruption.AffectedSampleIDs = appendUnique(disruption.AffectedSampleIDs, id)
			}
			status, replacement := e.replanJourney(t, journey, "disruption:"+resourceType,
				excludedLocations, excludedConnections)
			statuses[status] = true
			if replacement != nil {
				disruption.ReplacementPlanIDs = appendUnique(disruption.ReplacementPlanIDs, replacement.JourneyID)
			}
		}
		disruption.ReplanStatus = summariseReplan(statuses)
		e.disruptions[disruption.DisruptionID] = disruption
		t.saveDisruption(disruption)

		subjects := append([]string{disruption.DisruptionID, resourceID}, disruption.AffectedSampleIDs...)
		t.audit("report_disruption", "disruption", disruption.DisruptionID, true, map[string]any{
			"resourceType": resourceType, "resourceId": resourceID, "reason": reason,
			"occurredAt": formatTime(occurredAt), "replanStatus": disruption.ReplanStatus,
			"affectedSampleIds": disruption.AffectedSampleIDs,
			"replacementPlanIds": disruption.ReplacementPlanIDs,
		}, subjects...)
		t.event("disruption_reported", "disruption", disruption.DisruptionID, map[string]any{
			"disruptionId": disruption.DisruptionID, "resourceType": resourceType,
			"resourceId": resourceID, "replanStatus": disruption.ReplanStatus,
		}, operationsAudience()...)

		return map[string]any{
			"disruptionId":       disruption.DisruptionID,
			"affectedSampleIds":  stringsOrEmpty(disruption.AffectedSampleIDs),
			"replacementPlanIds": stringsOrEmpty(disruption.ReplacementPlanIDs),
			"replanStatus":       disruption.ReplanStatus,
		}, 201, nil
	})
}

func summariseReplan(statuses map[string]bool) string {
	switch {
	case statuses["expired"]:
		return "expired"
	case statuses["exception"]:
		return "exception"
	case statuses["replaced"]:
		return "replaced"
	default:
		return "not_required"
	}
}

func validResourceType(t string) bool {
	switch t {
	case "location", "node", "laboratory", "connection", "route", "worker", "capacity":
		return true
	}
	return false
}

func (e *Engine) journeysUsingLocation(locationID string) []*domain.Journey {
	var out []*domain.Journey
	for _, journey := range e.journeys {
		if !journey.Unfinished() {
			continue
		}
		for _, stop := range journey.Stops {
			// A stop already completed does not need replanning.
			if stop.LocationID == locationID && stop.CompletedAt == nil {
				out = append(out, journey)
				break
			}
		}
	}
	sortJourneys(out)
	return out
}

func (e *Engine) journeysUsingConnection(connectionID string) []*domain.Journey {
	var out []*domain.Journey
	for _, journey := range e.journeys {
		if !journey.Unfinished() {
			continue
		}
		for _, id := range journey.AssignmentIDs {
			a := e.assignments[id]
			if a != nil && a.ConnectionID == connectionID && !a.Terminal() {
				out = append(out, journey)
				break
			}
		}
	}
	sortJourneys(out)
	return out
}

func (e *Engine) journeysWithWorker(workerID string) []*domain.Journey {
	var out []*domain.Journey
	for _, journey := range e.journeys {
		if !journey.Unfinished() {
			continue
		}
		for _, id := range journey.AssignmentIDs {
			a := e.assignments[id]
			if a == nil || a.Terminal() {
				continue
			}
			if a.WorkerID == workerID || a.OfferedToID == workerID {
				out = append(out, journey)
				break
			}
		}
	}
	sortJourneys(out)
	return out
}

func sortJourneys(list []*domain.Journey) {
	sort.Slice(list, func(i, j int) bool { return list[i].JourneyID < list[j].JourneyID })
}

func sortStrings(list []string) { sort.Strings(list) }
