{"command":"create","path":"/workspace/backend/internal/core/editplan.go","file_text":"package core

import (
	"context"

	"labdelivery/internal/domain"
)

// EditActivePlanInput is a dispatcher change to an unfinished journey.
type EditActivePlanInput struct {
	JourneyID           string
	ExpectedPlanVersion int
	ChangeType          string
	Changes             map[string]any
}

var editChangeTypes = map[string]bool{
	"add_stop": true, "remove_stop": true, "reorder_stops": true, "replace_worker": true,
	"reassign_worker": true, "merge_samples": true, "split_samples": true, "split_batch": true,
	"cancel_work": true, "reroute": true, "replace_route": true,
}

// EditActivePlan changes an unfinished journey. Every change revalidates the affected legs
// and reservations; a change that fails validation is rejected and the plan is kept.
func (e *Engine) EditActivePlan(ctx context.Context, p *Principal, in EditActivePlanInput,
	idemKey, idemHash string) (any, int, error) {
	if err := e.requireRole(p, "edit active plans", domain.RoleDispatcher, domain.RoleAdministrator); err != nil {
		return nil, 0, err
	}
	if idemKey == "" {
		return nil, 0, errIdempotencyRequired()
	}
	if !editChangeTypes[in.ChangeType] {
		return nil, 0, errBadRequest("invalid_change_type", "unknown changeType")
	}
	return e.mutate(ctx, "edit_active_plan", idemKey, idemHash, p.User.UserID, func(t *txn) (any, int, error) {
		t.actor, t.role = p.User, p.ActiveRole
		journey := e.journeys[in.JourneyID]
		if journey == nil {
			return nil, 0, errNotFound("journey not found")
		}
		if err := checkPlanVersion(journey, in.ExpectedPlanVersion); err != nil {
			return nil, 0, err
		}
		if err := requireActivePlan(journey); err != nil {
			return nil, 0, err
		}

		var result any
		var err error
		switch in.ChangeType {
		case "add_stop":
			err = e.editAddStop(t, journey, in.Changes)
		case "remove_stop":
			err = e.editRemoveStop(t, journey, in.Changes)
		case "reorder_stops":
			err = e.editReorderStops(t, journey, in.Changes)
		case "replace_worker", "reassign_worker":
			err = e.editReplaceWorker(t, journey, in.Changes)
		case "merge_samples":
			err = e.editMergeSamples(t, journey, in.Changes)
		case "split_samples", "split_batch":
			result, err = e.editSplitSamples(t, journey, in.Changes)
		case "cancel_work":
			err = e.editCancelWork(t, journey, in.Changes)
		case "reroute", "replace_route":
			err = e.editReroute(t, journey)
		}
		if err != nil {
			return nil, 0, err
		}

		t.audit("edit_active_plan", "journey", journey.JourneyID, true, map[string]any{
			"changeType": in.ChangeType, "changes": in.Changes,
			"planVersion": journey.PlanVersion,
		}, journey.JourneyID)
		t.event("plan_edited", "journey", journey.JourneyID, map[string]any{
			"journeyId": journey.JourneyID, "changeType": in.ChangeType,
		}, operationsAudience()...)

		if split, ok := result.(*domain.Journey); ok {
			view := e.journeyPlanView(journey, nil)
			view.SplitJourney = e.journeyPlanView(split, nil)
			return view, 201, nil
		}
		return e.journeyPlanView(journey, nil), 201, nil
	})
}

// editAddStop inserts an intermediate stop and revalidates the resulting route.
func (e *Engine) editAddStop(t *txn, journey *domain.Journey, changes map[string]any) error {
	locationID := stringField(changes, "locationId", "location_id")
	if locationID == "" {
		return errConflict("invalid_stop", "locationId is required")
	}
	loc := e.locations[locationID]
	if loc == nil {
		return errConflict("invalid_stop", "unknown location")
	}
	if !loc.Active {
		return errConflict("invalid_stop", "location is not active")
	}
	dwell, hasDwell := intField(changes, "dwellMinutes", "dwell_minutes")
	if hasDwell && (dwell < 0 || dwell > 1440) {
		return errBadRequest("invalid_dwell", "dwellMinutes must be between 0 and 1440")
	}
	position, hasPosition := intField(changes, "sequence", "position")
	// New stops must be placed after work that is already finished.
	firstOpen := e.firstOpenStopIndex(journey)
	index := len(journey.Stops)
	if hasPosition {
		index = position - 1
		if index < firstOpen || index > len(journey.Stops) {
			return errConflict("invalid_stop_order", "the stop would reorder completed work")
		}
	}
	if index < firstOpen {
		return errConflict("completed_work_immutable", "cannot insert a stop before completed work")
	}

	stop := domain.Stop{
		StopID:       newUUID(),
		LocationID:   locationID,
		StopType:     domain.StopHandoff,
		EstimatedAt:  t.now,
		DwellMinutes: dwell,
		Coordinate:   loc.Coordinate,
	}
	stops := append([]domain.Stop{}, journey.Stops[:index]...)
	stops = append(stops, stop)
	stops = append(stops, journey.Stops[index:]...)

	return e.applyStopChange(t, journey, stops)
}

func (e *Engine) editRemoveStop(t *txn, journey *domain.Journey, changes map[string]any) error {
	stopID := stringField(changes, "stopId", "stop_id")
	if stopID == "" {
		return errConflict("invalid_stop", "stopId is required")
	}
	index := -1
	for i, s := range journey.Stops {
		if s.StopID == stopID {
			index = i
			break
		}
	}
	if index < 0 {
		return errConflict("invalid_stop", "unknown stop")
	}
	if journey.Stops[index].CompletedAt != nil {
		return errConflict("completed_work_immutable", "a completed stop cannot be removed")
	}
	if journey.Stops[index].StopType == domain.StopDelivery {
		return errConflict("invalid_stop", "the delivery stop cannot be removed")
	}
	stops := append([]domain.Stop{}, journey.Stops[:index]...)
	stops = append(stops, journey.Stops[index+1:]...)
	return e.applyStopChange(t, journey, stops)
}

func (e *Engine) editReorderStops(t *txn, journey *domain.Journey, changes map[string]any) error {
	order := stringSliceField(changes, "stopIds", "stop_ids", "order")
	if len(order) != len(journey.Stops) {
		return errConflict("ambiguous_stop_order", "the new order must list every stop exactly once")
	}
	byID := map[string]domain.Stop{}
	for _, s := range journey.Stops {
		byID[s.StopID] = s
	}
	stops := make([]domain.Stop, 0, len(order))
	seen := map[string]bool{}
	for _, id := range order {
		stop, ok := byID[id]
		if !ok || seen[id] {
			return errConflict("ambiguous_stop", "unknown or duplicated stop in the new order")
		}
		seen[id] = true
		stops = append(stops, stop)
	}
	// Completed stops must keep their original position.
	for i, s := range journey.Stops {
		if s.CompletedAt != nil && stops[i].StopID != s.StopID {
			return errConflict("completed_work_immutable", "completed stops cannot be reordered")
		}
	}
	return e.applyStopChange(t, journey, stops)
}

// applyStopChange validates a new stop order against the network before accepting it.
func (e *Engine) applyStopChange(t *txn, journey *domain.Journey, stops []domain.Stop) error {
	// Every consecutive pair must be joined by an active connection with capacity.
	for i := 0; i+1 < len(stops); i++ {
		if stops[i].LocationID == stops[i+1].LocationID {
			return errConflict("invalid_stop_order", "consecutive stops must differ")
		}
		conn := e.findConnection(stops[i].LocationID, stops[i+1].LocationID)
		if conn == nil {
			return errConflict("invalid_route", "no active connection between consecutive stops")
		}
		cooled := e.journeyRequiresCooled(journey)
		if cooled && !conn.Cooled {
			return errConflict("invalid_route", "the route must be cooled end to end")
		}
		if !connectionHasCapacity(conn, cooled) {
			return errConflict("capacity_exhausted", "transport capacity is exhausted on the new route")
		}
	}
	final := stops[len(stops)-1]
	lab := e.locations[final.LocationID]
	if lab == nil || !lab.FunctionActive(domain.FunctionLaboratory) {
		return errConflict("invalid_destination", "the final stop must be an active laboratory")
	}
	for _, sampleID := range journey.SampleIDs {
		sample := e.samples[sampleID]
		if sample == nil || !lab.Accepts(sample.SampleTypeID) {
			return errConflict("invalid_destination", "the laboratory does not accept every sample")
		}
	}

	// Re-time the plan and confirm every sample can still meet its deadline.
	cursor := t.now
	if len(stops) > 0 && stops[0].CompletedAt != nil {
		cursor = *stops[0].CompletedAt
	}
	for i := range stops {
		stops[i].Sequence = i + 1
		if i > 0 {
			conn := e.findConnection(stops[i-1].LocationID, stops[i].LocationID)
			if conn != nil {
				cursor = cursor.Add(minutes(conn.TravelMinutes))
			}
		}
		if stops[i].CompletedAt != nil {
			cursor = *stops[i].CompletedAt
		} else {
			cursor = cursor.Add(minutes(stops[i].DwellMinutes))
			stops[i].EstimatedAt = cursor
		}
	}
	for _, sampleID := range journey.SampleIDs {
		sample := e.samples[sampleID]
		if sample != nil && cursor.After(sample.DeliveryDeadline) {
			return errConflict("deadline_exceeded", "the change would miss a delivery deadline")
		}
	}

	journey.Stops = stops
	journey.EstimatedDeliveryAt = timePtr(cursor)
	journey.LaboratoryID = final.LocationID
	journey.PlanVersion++
	e.realignTransportLegs(t, journey)
	t.saveJourney(journey)
	return nil
}

// realignTransportLegs rebuilds the unfinished transport legs to follow the current stops.
func (e *Engine) realignTransportLegs(t *txn, journey *domain.Journey) {
	var open []domain.Stop
	for _, s := range journey.Stops {
		if s.CompletedAt == nil {
			open = append(open, s)
		}
	}
	var legs []*domain.Assignment
	for _, id := range journey.AssignmentIDs {
		a := e.assignments[id]
		if a != nil && a.Kind == domain.AssignmentTransport && !a.Terminal() && !a.InProgress() {
			legs = append(legs, a)
		}
	}
	needed := 0
	if len(open) > 1 {
		needed = len(open) - 1
	}
	cooled := e.journeyRequiresCooled(journey)

	for i := 0; i < needed; i++ {
		from, to := open[i], open[i+1]
		conn := e.findConnection(from.LocationID, to.LocationID)
		if i < len(legs) {
			a := legs[i]
			a.FromLocationID = from.LocationID
			a.ToLocationID = to.LocationID
			a.PickupStopID = from.StopID
			a.DropoffStopID = to.StopID
			if conn != nil {
				a.ConnectionID = conn.ConnectionID
			}
			t.saveAssignment(a)
			continue
		}
		a := &domain.Assignment{
			AssignmentID:   newUUID(),
			Kind:           domain.AssignmentTransport,
			JourneyID:      journey.JourneyID,
			SampleID:       journey.SampleIDs[0],
			SampleIDs:      append([]string{}, journey.SampleIDs...),
			Sequence:       len(journey.AssignmentIDs) + 1,
			Status:         domain.AssignStatusPending,
			FromLocationID: from.LocationID,
			ToLocationID:   to.LocationID,
			RequiredRole:   domain.RoleDeliveryPartner,
			Cooled:         cooled,
			PickupStopID:   from.StopID,
			DropoffStopID:  to.StopID,
			DeclinedByIDs:  []string{},
			CreatedAt:      t.now,
		}
		if conn != nil {
			a.ConnectionID = conn.ConnectionID
		}
		e.assignments[a.AssignmentID] = a
		journey.AssignmentIDs = append(journey.AssignmentIDs, a.AssignmentID)
		t.saveAssignment(a)
		e.offerAssignment(t, a)
	}
	// Legs that the shortened route no longer needs are cancelled.
	for i := needed; i < len(legs); i++ {
		legs[i].Status = domain.AssignStatusCancelled
		t.saveAssignment(legs[i])
		t.audit("cancel_assignment", "assignment", legs[i].AssignmentID, true, map[string]any{
			"reason": "route_shortened", "journeyId": journey.JourneyID,
		}, legs[i].AssignmentID, journey.JourneyID)
	}
}

func (e *Engine) firstOpenStopIndex(journey *domain.Journey) int {
	for i, s := range journey.Stops {
		if s.CompletedAt == nil {
			return i
		}
	}
	return len(journey.Stops)
}

func (e *Engine) findConnection(fromID, toID string) *domain.Connection {
	var best *domain.Connection
	for _, conn := range e.connections {
		if !conn.Active || conn.FromLocationID != fromID || conn.ToLocationID != toID {
			continue
		}
		if best == nil || conn.TravelMinutes < best.TravelMinutes {
			best = conn
		}
	}
	return best
}

func (e *Engine) journeyRequiresCooled(journey *domain.Journey) bool {
	for _, id := range journey.SampleIDs {
		sample := e.samples[id]
		if sample == nil {
			continue
		}
		if st := e.sampleTypes[sample.SampleTypeID]; st != nil && st.RequiresCooledRoute {
			return true
		}
	}
	return false
}

// editReplaceWorker moves an assignment to another eligible worker or re-offers it.
func (e *Engine) editReplaceWorker(t *txn, journey *domain.Journey, changes map[string]any) error {
	assignmentID := stringField(changes, "assignmentId", "assignment_id")
	if assignmentID == "" {
		return errBadRequest("invalid_worker", "assignmentId is required")
	}
	a := e.assignments[assignmentID]
	if a == nil || a.JourneyID != journey.JourneyID {
		return errConflict("invalid_assignment", "assignment is not part of this journey")
	}
	if a.Status == domain.AssignStatusCompleted {
		return errConflict("completed_work_immutable", "completed work cannot be reassigned")
	}
	if a.InProgress() {
		return errConflict("work_in_progress", "work already under way cannot be reassigned")
	}
	previous := a.WorkerID

	workerID := stringField(changes, "workerId", "worker_id")
	if workerID != "" {
		worker := e.users[workerID]
		if worker == nil {
			return errBadRequest("invalid_worker", "worker not found")
		}
		if !e.eligibleWorker(worker, a, t.now) {
			return errConflict("ineligible_worker", "the worker is not eligible for this assignment")
		}
		a.WorkerID = worker.UserID
		a.Status = domain.AssignStatusAccepted
		a.OfferedToID = ""
		a.OfferExpiresAt = nil
		worker.TotalAssignments++
		worker.LastAssignedAt = timePtr(t.now)
		t.saveUser(worker)
		t.saveAssignment(a)
	} else {
		a.WorkerID = ""
		a.Status = domain.AssignStatusPending
		t.saveAssignment(a)
		e.offerAssignment(t, a)
	}

	journey.PlanVersion++
	t.saveJourney(journey)
	t.audit("replace_worker", "assignment", a.AssignmentID, true, map[string]any{
		"previousWorkerId": previous, "workerId": a.WorkerID, "journeyId": journey.JourneyID,
	}, a.AssignmentID, journey.JourneyID, a.SampleID)
	return nil
}

func (e *Engine) editMergeSamples(t *txn, journey *domain.Journey, changes map[string]any) error {
	incoming := stringSliceField(changes, "sampleIds", "sample_ids")
	if len(incoming) == 0 {
		return errConflict("invalid_batch", "sampleIds is required")
	}
	merged := append([]string{}, journey.SampleIDs...)
	for _, id := range incoming {
		sample := e.samples[id]
		if sample == nil {
			return errNotFound("sample not found")
		}
		if sample.Terminal() {
			return errConflict("invalid_batch", "a terminal sample cannot be batched")
		}
		merged = appendUnique(merged, id)
	}
	if err := e.validateBatch(merged, journey.LaboratoryID); err != nil {
		return err
	}
	if err := e.reshapeJourney(t, journey, merged); err != nil {
		return err
	}
	journey.RouteMode = domain.RouteBatched
	t.saveJourney(journey)
	return nil
}

func (e *Engine) editSplitSamples(t *txn, journey *domain.Journey, changes map[string]any) (any, error) {
	moving := stringSliceField(changes, "sampleIds", "sample_ids")
	if len(moving) == 0 {
		return nil, errConflict("invalid_split", "sampleIds is required")
	}
	for _, id := range moving {
		if !containsString(journey.SampleIDs, id) {
			return nil, errConflict("invalid_split", "sample is not part of this journey")
		}
	}
	if len(moving) >= len(journey.SampleIDs) {
		return nil, errConflict("invalid_split", "at least one sample must remain on the journey")
	}
	if e.workStarted(journey, moving) {
		return nil, errConflict("split_in_progress", "work for these samples has already started")
	}
	remaining := []string{}
	for _, id := range journey.SampleIDs {
		if !containsString(moving, id) {
			remaining = append(remaining, id)
		}
	}
	split, err := e.rebuildJourneyFor(t, journey, moving, journey.JourneyID)
	if err != nil {
		return nil, err
	}
	if err := e.reshapeJourney(t, journey, remaining); err != nil {
		return nil, err
	}
	return split, nil
}

func (e *Engine) editCancelWork(t *txn, journey *domain.Journey, changes map[string]any) error {
	assignmentID := stringField(changes, "assignmentId", "assignment_id")
	if assignmentID == "" {
		// Cancel the whole unfinished plan.
		e.cancelUnfinishedWork(t, journey, "dispatcher_cancelled")
		journey.Status = domain.JourneyStatusCancelled
		journey.PlanVersion++
		e.releaseJourneyReservations(t, journey)
		t.saveJourney(journey)
		return nil
	}
	a := e.assignments[assignmentID]
	if a == nil || a.JourneyID != journey.JourneyID {
		return errConflict("invalid_assignment", "assignment is not part of this journey")
	}
	if a.Status == domain.AssignStatusCompleted {
		return errConflict("completed_work_immutable", "completed work cannot be cancelled")
	}
	a.Status = domain.AssignStatusCancelled
	t.saveAssignment(a)
	journey.PlanVersion++
	t.saveJourney(journey)
	t.audit("cancel_assignment", "assignment", a.AssignmentID, true, map[string]any{
		"reason": "dispatcher_cancelled", "journeyId": journey.JourneyID,
	}, a.AssignmentID, journey.JourneyID, a.SampleID)
	return nil
}

func (e *Engine) editReroute(t *txn, journey *domain.Journey) error {
	return e.reshapeJourney(t, journey, journey.SampleIDs)
}

func stringField(m map[string]any, keys ...string) string {
	for _, k := range keys {
		if v, ok := m[k]; ok {
			if s, ok := v.(string); ok && s != "" {
				return s
			}
		}
	}
	return ""
}

func intField(m map[string]any, keys ...string) (int, bool) {
	for _, k := range keys {
		v, ok := m[k]
		if !ok {
			continue
		}
		switch n := v.(type) {
		case float64:
			return int(n), true
		case int:
			return n, true
		}
	}
	return 0, false
}

func stringSliceField(m map[string]any, keys ...string) []string {
	for _, k := range keys {
		v, ok := m[k]
		if !ok {
			continue
		}
		if list, ok := v.([]any); ok {
			out := make([]string, 0, len(list))
			for _, item := range list {
				if s, ok := item.(string); ok {
					out = append(out, s)
				}
			}
			if len(out) > 0 {
				return out
			}
		}
	}
	return nil
}

