{"command":"create","path":"/workspace/backend/internal/api/server.go","file_text":"// Package api exposes the pinned HTTP contract over the domain engine.
package api

import (
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strings"

	"labdelivery/internal/core"
)

// Server routes contract operations to the engine and serves the SPA.
type Server struct {
	engine *core.Engine
	mux    *http.ServeMux
	static http.Handler
}

// Options configures static asset serving.
type Options struct {
	FrontendDir string
	MapAssetDir string
	MapCenter   string
	MapBounds   string
}

// New builds the HTTP handler for the whole application.
func New(engine *core.Engine, opts Options) *Server {
	s := &Server{engine: engine, mux: http.NewServeMux()}
	s.routes()
	s.static = newStaticHandler(opts)
	return s
}

func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Cache-Control", "no-store")
	if r.URL.Path == "/ready" || r.URL.Path == "/api/events" ||
		strings.HasPrefix(r.URL.Path, "/api/") {
		s.mux.ServeHTTP(w, r)
		return
	}
	s.static.ServeHTTP(w, r)
}

// ---------------------------------------------------------------- envelopes

type errorBody struct {
	Error string `json:"error"`
	Code  string `json:"code"`
}

func writeJSON(w http.ResponseWriter, status int, body any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(body)
}

// writeData wraps a payload in the contract's {"data": ...} envelope.
func writeData(w http.ResponseWriter, status int, data any) {
	writeJSON(w, status, map[string]any{"data": data})
}

func writeErr(w http.ResponseWriter, status int, code, message string) {
	writeJSON(w, status, errorBody{Error: message, Code: code})
}

// writeAPIError maps a domain error onto its pinned status and code.
func writeAPIError(w http.ResponseWriter, err error) {
	var apiErr *core.APIError
	if errors.As(err, &apiErr) {
		writeErr(w, apiErr.Status, apiErr.Code, apiErr.Message)
		return
	}
	writeErr(w, http.StatusInternalServerError, "internal_error", err.Error())
}

const maxBodyBytes = 4 << 20

// decode reads a JSON request body. An absent body is treated as an empty object
// so that operations whose fields are all optional can be called without one.
func decode(w http.ResponseWriter, r *http.Request, dst any) ([]byte, bool) {
	raw, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxBodyBytes))
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "request body could not be read")
		return nil, false
	}
	if len(strings.TrimSpace(string(raw))) == 0 {
		raw = []byte("{}")
	}
	dec := json.NewDecoder(strings.NewReader(string(raw)))
	if err := dec.Decode(dst); err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "request body is not valid JSON for this operation")
		return nil, false
	}
	return raw, true
}

// ---------------------------------------------------------------- middleware

type handlerFunc func(http.ResponseWriter, *http.Request, *core.Principal, []byte)

// post registers an authenticated POST operation.
func (s *Server) post(path string, fn handlerFunc) {
	s.mux.HandleFunc(path, func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			writeErr(w, http.StatusMethodNotAllowed, "method_not_allowed", "this operation requires POST")
			return
		}
		p, ok := s.authenticate(w, r)
		if !ok {
			return
		}
		fn(w, r, p, nil)
	})
}

// postPublic registers an unauthenticated POST operation.
func (s *Server) postPublic(path string, fn func(http.ResponseWriter, *http.Request)) {
	s.mux.HandleFunc(path, func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			writeErr(w, http.StatusMethodNotAllowed, "method_not_allowed", "this operation requires POST")
			return
		}
		fn(w, r)
	})
}

// get registers an authenticated GET operation.
func (s *Server) get(path string, fn handlerFunc) {
	s.mux.HandleFunc(path, func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			writeErr(w, http.StatusMethodNotAllowed, "method_not_allowed", "this operation requires GET")
			return
		}
		p, ok := s.authenticate(w, r)
		if !ok {
			return
		}
		fn(w, r, p, nil)
	})
}

func bearerToken(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if h == "" {
		return ""
	}
	if len(h) >= 7 && strings.EqualFold(h[:7], "bearer ") {
		return strings.TrimSpace(h[7:])
	}
	return ""
}

func (s *Server) authenticate(w http.ResponseWriter, r *http.Request) (*core.Principal, bool) {
	p, err := s.engine.Authorize(bearerToken(r))
	if err != nil {
		writeAPIError(w, err)
		return nil, false
	}
	return p, true
}

// pathTail returns the final path segment after prefix.
func pathTail(path, prefix string) string {
	rest := strings.TrimPrefix(path, prefix)
	rest = strings.Trim(rest, "/")
	if rest == "" || strings.Contains(rest, "/") {
		return ""
	}
	return rest
}
