{"command":"create","path":"/workspace/backend/cmd/server/main.go","file_text":"// Command server runs the lab sample pickup and delivery application.
package main

import (
	"context"
	"errors"
	"flag"
	"log"
	"net/http"
	"os"
	"os/signal"
	"strings"
	"syscall"
	"time"

	"labdelivery/internal/api"
	"labdelivery/internal/core"
	"labdelivery/internal/store"
)

func main() {
	migrate := flag.Bool("migrate", false, "apply migrations and exit")
	reset := flag.Bool("reset", false, "clear application state, migrate and exit")
	flag.Parse()

	addr := env("LISTEN_ADDR", "127.0.0.1:8080")
	dsn := env("DATABASE_URL", "postgres:///labdelivery")

	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()

	st, err := openStore(ctx, dsn)
	if err != nil {
		log.Fatalf("database unavailable: %v", err)
	}
	defer st.Close()

	if err := st.Migrate(ctx); err != nil {
		log.Fatalf("migrations failed: %v", err)
	}
	if *reset {
		if err := st.Truncate(ctx); err != nil {
			log.Fatalf("reset failed: %v", err)
		}
		log.Print("application state cleared")
		return
	}
	if *migrate {
		log.Print("migrations applied")
		return
	}

	engine, err := core.New(ctx, st, core.DefaultConfig())
	if err != nil {
		log.Fatalf("engine startup failed: %v", err)
	}
	if err := engine.EnsureDefaultSampleTypes(ctx); err != nil {
		log.Fatalf("sample type seeding failed: %v", err)
	}
	if err := engine.EnsureInitialAdministrator(ctx,
		os.Getenv("ADMIN_USERNAME"), os.Getenv("ADMIN_PASSWORD")); err != nil {
		log.Fatalf("administrator bootstrap failed: %v", err)
	}
	engine.PublishServiceability(ctx)

	go background(ctx, engine)

	handler := api.New(engine, api.Options{
		FrontendDir: env("FRONTEND_DIR", "frontend/dist"),
		MapAssetDir: os.Getenv("OFFLINE_MAP_ASSET_DIR"),
		MapCenter:   os.Getenv("OFFLINE_MAP_CENTER"),
		MapBounds:   os.Getenv("OFFLINE_MAP_BOUNDS"),
	})

	srv := &http.Server{
		Addr:              addr,
		Handler:           handler,
		ReadHeaderTimeout: 15 * time.Second,
		// Streaming responses must not be cut off by a write deadline.
		WriteTimeout: 0,
		IdleTimeout:  120 * time.Second,
	}

	go func() {
		<-ctx.Done()
		shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		_ = srv.Shutdown(shutdownCtx)
	}()

	log.Printf("listening on http://%s", addr)
	if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
		log.Fatalf("server stopped: %v", err)
	}
}

// openStore waits briefly for the database so start ordering is not fatal.
func openStore(ctx context.Context, dsn string) (*store.Store, error) {
	var lastErr error
	for attempt := 0; attempt < 30; attempt++ {
		st, err := store.Open(ctx, dsn)
		if err == nil {
			return st, nil
		}
		lastErr = err
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-time.After(time.Second):
		}
	}
	return nil, lastErr
}

// background drives time-based rules: offer timeouts, unavailable-worker
// exceptions, session expiry and serviceability recomputation.
func background(ctx context.Context, engine *core.Engine) {
	ticker := time.NewTicker(2 * time.Second)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			engine.RunDueWork(ctx)
			engine.PublishServiceability(ctx)
			engine.PurgeExpiredSessions(ctx)
		}
	}
}

func env(key, fallback string) string {
	if v := strings.TrimSpace(os.Getenv(key)); v != "" {
		return v
	}
	return fallback
}
