{"command":"create","path":"/workspace/backend/internal/core/due.go","file_text":"package core

import (
	"context"
	"sort"

	"labdelivery/internal/domain"
)

// RunDueWork advances the time-based rules of the system: offers that received no
// response become declines and are re-offered, assignments that never found a
// qualified worker raise their own exception, and samples that can no longer be
// received before their deadline are flagged as missed deadlines.
func (e *Engine) RunDueWork(ctx context.Context) {
	e.expireStaleOffers(ctx)
	e.flagMissedDeadlines(ctx)
}

// flagMissedDeadlines marks unfinished samples whose delivery deadline has passed.
// The reason differs from a no-qualified-worker exception so the two are
// distinguishable in monitoring and audit.
func (e *Engine) flagMissedDeadlines(ctx context.Context) {
	e.mu.Lock()
	now := e.now()
	var overdue []string
	for id, sample := range e.samples {
		if sample.Terminal() || sample.Status == domain.SampleStatusException {
			continue
		}
		if sample.Status == domain.SampleStatusUnserviceable {
			continue
		}
		if sample.DeliveryDeadline.Before(now) {
			overdue = append(overdue, id)
		}
	}
	e.mu.Unlock()
	if len(overdue) == 0 {
		return
	}
	sort.Strings(overdue)
	for _, id := range overdue {
		_, _, _ = e.mutate(ctx, "deadline_exceeded:"+id, "", "", "", func(t *txn) (any, int, error) {
			sample := e.samples[id]
			if sample == nil || sample.Terminal() || sample.Status == domain.SampleStatusException ||
				!sample.DeliveryDeadline.Before(t.now) {
				return map[string]any{"skipped": true}, 200, nil
			}
			sample.Status = domain.SampleStatusException
			sample.Exception = &domain.ExceptionInfo{
				Reason:     "deadline_exceeded",
				Kind:       "deadline",
				Detail:     "the delivery deadline passed before laboratory receipt",
				OccurredAt: t.now,
			}
			t.saveSample(sample)
			t.audit("sample_exception", "sample", sample.SampleID, true, map[string]any{
				"reason":           "deadline_exceeded",
				"deliveryDeadline": formatTime(sample.DeliveryDeadline),
			}, sample.SampleID, sample.ActiveJourneyID)
			t.event("sample_exception", "sample", sample.SampleID, map[string]any{
				"reason": "deadline_exceeded",
			}, append(operationsAudience(), userAudience(sample.RequesterID))...)
			return map[string]any{"flagged": true}, 200, nil
		})
	}
}
