covered = {}


def resolve(method, path):
    for tmpl, item in CONTRACT["paths"].items():
        op = item.get(method.lower())
        if not op:
            continue
        t = tmpl.strip("/").split("/")
        p = path.split("?")[0].strip("/").split("/")
        if len(t) == len(p) and all(a.startswith("{") or a == b for a, b in zip(t, p)):
            return tmpl, op
    return None, None


def check_schema(op, tmpl, method, status, payload, label):
    global validated
    responses = op.get("responses", {})
    spec = responses.get(str(status))
    if spec is None:
        failures.append(f"{label}: HTTP {status} is not declared for {method} {tmpl} "
                        f"(contract declares {sorted(responses)})")
        return
    schema = spec.get("content", {}).get("application/json", {}).get("schema")
    if schema is None:
        return
    full = copy.deepcopy(schema)
    full["components"] = CONTRACT["components"]
    errs = sorted(Draft202012Validator(full).iter_errors(payload), key=lambda e: e.json_path)
    if errs:
        e = errs[0]
        failures.append(f"{label}: HTTP {status} body violates contract at "
                        f"{e.json_path}: {e.message[:200]}")
    else:
        validated += 1


def call(path, body=None, token=None, method=None, expect=200, label=None):
    data = json.dumps(body).encode() if body is not None else None
    headers = {}
    if data:
        headers["Content-Type"] = "application/json"
    if token:
        headers["Authorization"] = "Bearer " + token
    method = method or ("POST" if body is not None else "GET")
    req = urllib.request.Request(BASE + path, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(req) as r:
            status, raw = r.status, r.read()
    except urllib.error.HTTPError as e:
        status, raw = e.code, e.read()
    try:
        payload = json.loads(raw or b"{}")
    except Exception:
        payload = {"_raw": raw[:200].decode(errors="replace")}

    label = label or f"{method} {path}"
    tmpl, op = resolve(method, path)
    if op is None:
        failures.append(f"{label}: {method} {path} is not in the contract")
    else:
        covered.setdefault(op["operationId"], set()).add(status)
        check_schema(op, tmpl, method, status, payload, label)

    if status != expect:
        failures.append(f"{label}: expected HTTP {expect} got {status} -> "
                        f"{json.dumps(payload)[:300]}")
        print(f"  FAIL {label}: {status} {json.dumps(payload)[:200]}")
    else:
        print(f"  ok   {label}: {status}")
    return status, payload.get("data", payload)


