{"command":"str_replace","path":"/workspace/backend/internal/core/bootstrap.go","old_str":"// ReadUIBootstrap returns identity plus the role-appropriate first view of state.","new_str":"// UIReferenceView carries the option lists the forms need. The pinned contract
// fixes the shape of /api/ui/bootstrap and has no sample-type listing operation,
// so this reference data is served outside the pinned /api surface.
type UIReferenceView struct {
	SampleTypes  []*domain.SampleType `json:"sampleTypes"`
	Locations    []*UIReferenceNode   `json:"locations"`
	Laboratories []*UIReferenceNode   `json:"laboratories"`
}

// UIReferenceNode is the minimum a form needs to offer a location choice.
type UIReferenceNode struct {
	LocationID string            `json:"locationId"`
	Name       string            `json:"name"`
	Coordinate domain.Coordinate `json:"coordinate"`
	Active     bool              `json:"active"`
}

// ReadUIReference lists sample types and selectable locations for the UI forms.
func (e *Engine) ReadUIReference(p *Principal) (any, error) {
	return e.read(func() (any, error) {
		view := &UIReferenceView{
			SampleTypes:  make([]*domain.SampleType, 0, len(e.sampleTypes)),
			Locations:    []*UIReferenceNode{},
			Laboratories: []*UIReferenceNode{},
		}
		for _, st := range e.sampleTypes {
			view.SampleTypes = append(view.SampleTypes, st)
		}
		sort.Slice(view.SampleTypes, func(i, j int) bool {
			return view.SampleTypes[i].Name < view.SampleTypes[j].Name
		})
		for _, loc := range e.locations {
			node := &UIReferenceNode{
				LocationID: loc.LocationID,
				Name:       loc.Name,
				Coordinate: loc.Coordinate,
				Active:     loc.Active,
			}
			view.Locations = append(view.Locations, node)
			if loc.Functions[domain.FunctionLaboratory] {
				view.Laboratories = append(view.Laboratories, node)
			}
		}
		sort.Slice(view.Locations, func(i, j int) bool {
			return view.Locations[i].Name < view.Locations[j].Name
		})
		sort.Slice(view.Laboratories, func(i, j int) bool {
			return view.Laboratories[i].Name < view.Laboratories[j].Name
		})
		return view, nil
	})
}

