{"command":"str_replace","path":"/workspace/backend/internal/core/offers.go","old_str":"// candidateWorkers ranks eligible workers fairly: least loaded first, then least recently","new_str":"// authorizeAssignmentSite rejects a caller whose posting does not match the node or
// laboratory an assignment belongs to. Transport and collection work is not site-bound.
func (e *Engine) authorizeAssignmentSite(p *Principal, a *domain.Assignment) error {
	var site string
	switch a.Kind {
	case domain.AssignmentNode:
		site = a.NodeID
	case domain.AssignmentLaboratory:
		site = a.LaboratoryID
	default:
		return nil
	}
	worker := e.users[p.User.UserID]
	if worker == nil || site == "" || worker.AssignedLocationID != site {
		return errForbiddenCode("ineligible_worker",
			"this assignment belongs to a site you are not assigned to")
	}
	return nil
}

// candidateWorkers ranks eligible workers fairly: least loaded first, then least recently","security_risk":"LOW","summary":"Add site authorization helper"}

